   private void setCellState(int i, byte value) {
      if (this.cellStates[i] != value) {
         if (this.cellStates[i] == 0 != (value == 0)) {
            Item item = this.targets[i].item();
            int remaining = this.openCountByItem.getInt(item) + (value == 0 ? 1 : -1);
            if (remaining == 0) {
               this.openCountByItem.removeInt(item);
            } else {
               this.openCountByItem.put(item, remaining);
            }
         }

         if (this.chunkWork != null) {
            this.chunkWork.init(i, this.cellStates[i], value);
         }

         if (this.columnHead != null && this.cellStates[i] == 0 != (value == 0)) {
            this.dirtyColumns.set(this.columnIndex(this.targets[i].pos()));
         }

         this.workableCells.set(i, value == 0 || value == 2);
         this.placedCells.set(i, value == 2);
         if (this.componentMembers != null) {
            this.updateComponentCounts(i, this.cellStates[i], value);
         }

         if (this.cellStates[i] == 5) {
            this.failedTotal--;
         }

         if (value == 5) {
            this.failedTotal++;
         }

         if (this.cellStates[i] == 3) {
            this.placedCount--;
            if (this.isNonFlowCell(i)) {
               this.openCells++;
            }
         }

         if (value == 3) {
            this.placedCount++;
            if (this.isNonFlowCell(i)) {
               this.openCells--;
            }

            this.threatenedCells.remove(i);
         }

         this.cellStates[i] = value;
         if (value == 0 || value == 5) {
            this.dispatchedJobCells.remove(i);
         }

         this.cleanupAccess.markOwnerEntriesDirty(i);
         if (this.spatialIndex != null) {
            this.spatialIndex.setEligible(i, value == 0);
         }

         this.statuses++;
      }
   }

   private void dispatchCell(int i) {
      PrintMachineJob job = this.machineJobs.get(this.targets[i].pos().asLong());
      if (job != null
         && job.b_()
         && !this.env.getBlockState(this.targets[i].pos()).is(this.targets[i].wanted().getBlock())) {
         this.dispatchedJobCells.add(i);
      }

      this.setCellState(i, (byte)1);
      this.dispatchTick[i] = this.env.currentTick();
      this.dispatchedCells.add(i);
   }

   autismclient.ai.engine.PlacementGoal.PlaceConstraint constraintFor(int i) {
      Block block = this.targets[i].wanted().getBlock();
      if (!(block instanceof ChestBlock) && !block.hasDynamicShape()) {
         Object c = this.constraintCache.get(i);
         if (c == null) {
            autismclient.ai.engine.PlacementGoal.PlaceConstraint made = AiPrintRules.clickConstraint(this.targets[i], this.view);
            this.constraintCache.put(i, made == null ? NO_CONSTRAINT : made);
            return made;
         } else {
            return c == NO_CONSTRAINT ? null : (autismclient.ai.engine.PlacementGoal.PlaceConstraint)c;
         }
      } else {
         return AiPrintRules.clickConstraint(this.targets[i], this.view);
      }
   }

   boolean isLookFaced(int i) {
      autismclient.ai.engine.PlacementGoal.PlaceConstraint con = this.constraintFor(i);
      return con != null && con.fullDirection() && con.playerFacing() != null;
   }

