   public List<Item> neededMaterials(int max) {
      if (max <= 0) {
         return List.of();
      }

      if (this.materialForecastJob == null && (this.materialForecast == null || this.env.currentTick() - this.materialForecastTick >= 10L)) {
         this.materialForecastJob = new PrintCore.F();
      }

      if (this.materialForecastJob != null && this.materialForecastStepTick != this.env.currentTick()) {
         this.materialForecastStepTick = this.env.currentTick();
         if (this.materialForecastJob.advanceForecast()) {
            this.materialForecast = this.materialForecastJob.forecastItems();
            this.materialForecastJob = null;
            this.materialForecastTick = this.env.currentTick();
         }
      }

      LinkedHashSet<Item> out = new LinkedHashSet<>();
      if (this.requestedItem != null) {
         out.add(this.requestedItem);
      }

      if (this.phase == PrintCore.J.VERIFY && !this.machineJobs.isEmpty()) {
         Item item = this.machineJobs.get(this.machineJobs.firstLongKey()).item();
         if (item != Items.AIR && out.size() < max) {
            out.add(item);
         }
      }

      if (this.materialForecast != null) {
         for (Item item : this.materialForecast) {
            if (out.size() >= max) {
               break;
            }

            out.add(item);
         }
      }

      return new ArrayList<>(out);
   }

   boolean isNonFlowCell(int i) {
      return this.targets[i].kind() != autismclient.ai.print.PrintTarget.Inner_DataUtil.FLOW;
   }

   void refreshCell(int i) {
      PrintTarget t = this.targets[i];
      if (this.env.hasChunkAt(t.pos())) {
         BlockState live = this.view.getBlockState(t.pos());
         if (!live.is(t.wanted().getBlock())) {
            this.jobBlocksPlaced.remove(t.pos().asLong());
         }

         int before = this.cellStates[i];
         if (this.isCellFinished(i, live)) {
            if (this.slopePassStarted && this.slopeHelpers().containsKey(i) && this.verifiedRailSlopes.add(i) && before != 3) {
               this.progressFlags[i] = (byte)(this.progressFlags[i] & -3);
            }

            this.setCellState(i, (byte)3);
            this.dispatchedCells.remove(i);
            if (before != 3) {
               this.recordProgress(i, before);
            }
         } else if ((before != 5 || !this.isUnraisedSlope(i, live)) && this.cellStates[i] != 1) {
            if (t.kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLOW || t.kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.PARTNER) {
               this.setCellState(i, (byte)4);
            } else if (t.kind() != autismclient.ai.print.PrintTarget.Inner_DataUtil.FLUID && this.rules.isPlacedCorrectly(t, live)) {
               this.setCellState(i, (byte)2);
               if (before != 2 && before != 3) {
                  this.recordProgress(i, before);
               }
            } else if (this.cellStates[i] != 5) {
               this.setCellState(i, (byte)0);
            }
         }
      }
   }

   Int2ObjectOpenHashMap<BlockPos> slopeHelpers() {
      if (this.slopeHelperCells != null) {
         return this.slopeHelperCells;
      }

      this.slopeHelperCells = new Int2ObjectOpenHashMap<>();
      if (!SLOPE_HELPERS) {
         return this.slopeHelperCells;
      }

      for (int i = 0; i < this.targets.length; i++) {
         PrintTarget t = this.targets[i];
         if (t.kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.PLACE && t.wanted().getBlock() instanceof BaseRailBlock rail) {
            RailShape shape = t.wanted().getValue(rail.getShapeProperty());
            Direction var10000;
            switch (shape) {
               case ASCENDING_EAST:
                  var10000 = Direction.EAST;
                  break;
               case ASCENDING_WEST:
                  var10000 = Direction.WEST;
                  break;
               case ASCENDING_NORTH:
                  var10000 = Direction.NORTH;
                  break;
               case ASCENDING_SOUTH:
                  var10000 = Direction.SOUTH;
                  break;
               default:
                  var10000 = null;
            }

            Direction up = var10000;
            if (up != null) {
               BlockPos helper = t.pos().relative(up).above();
               if (this.cellIndexByPos.get(helper.asLong()) < 0) {
                  boolean alone = true;

                  for (Direction side : Plane.HORIZONTAL) {
                     for (int dy = -1; dy <= 1 && alone; dy++) {
                        long key = helper.relative(side).offset(0, dy, 0).asLong();
                        int j = this.cellIndexByPos.get(key);
                        if (j >= 0 && j != i && this.targets[j].wanted().getBlock() instanceof BaseRailBlock) {
                           alone = false;
                        }
                     }
                  }

                  if (alone) {
                     this.slopeHelperCells.put(i, helper);
                  }
               }
            }
         }
      }

      return this.slopeHelperCells;
   }

   public int railSlopesVerified() {
      return this.verifiedRailSlopes.size();
   }

   private boolean onlySlopesOpen() {
      int slopes = 0;

      for (Entry<BlockPos> e : this.slopeHelpers().int2ObjectEntrySet()) {
         int i = e.getIntKey();
         if (this.cellStates[i] != 3 && this.isNonFlowCell(i)) {
            slopes++;
         }
      }

      return this.openCells == slopes;
   }

   private PrintCore.PrintStep slopePassStep() {
      if (this.slopeHelpers().isEmpty()) {
         return null;
      }

      if (!this.slopePassStarted) {
         this.slopePassStarted = true;

         for (int i : this.slopeHelperCells.keySet()) {
            this.refreshCell(i);
         }
      }

      if (this.env.canUseFlight()) {
         for (int i : this.slopeHelperCells.keySet()) {
            if (this.cellStates[i] == 2 && this.isUnraisedSlope(i, this.view.getBlockState(this.targets[i].pos()))) {
               return new PrintCore.X();
            }
         }

         return null;
      } else {
         for (int i : this.slopeHelperCells.keySet()) {
            if (this.cellStates[i] == 2 && this.isUnraisedSlope(i, this.view.getBlockState(this.targets[i].pos()))) {
               return new PrintCore.ae();
            }
         }

         return null;
      }
   }

   private void noteFlatSlope(int i, String why) {
      if (this.flatSlopes.add(i)) {
         this.logTrace("slope: " + this.targets[i].pos().toShortString() + " stays flat: " + why);
         if (this.skipNotes.size() < 16) {
            this.skipNotes.add(this.targets[i].pos().toShortString() + ": rail left flat (" + why + ")");
         }

         this.giveUpCell(i, "saved rail shape was not reproduced: " + why);
      }
   }

   private boolean get(BlockPos helper) {
      BlockState temp = this.temporaryBlocks.get(helper.asLong());
      return temp != null && temp.getBlock() instanceof BaseRailBlock && this.view.getBlockState(helper).getBlock() instanceof BaseRailBlock;
   }

   boolean isUnraisedSlope(int i, BlockState live) {
      if (this.slopePassStarted && this.slopeHelpers().containsKey(i)) {
         BlockState wanted = this.targets[i].wanted();
         return live.is(wanted.getBlock()) && live.getBlock() instanceof BaseRailBlock rail
            ? live.getValue(rail.getShapeProperty()) != wanted.getValue(rail.getShapeProperty())
            : false;
      } else {
         return false;
      }
   }

   private boolean isCellFinished(int i, BlockState live) {
      PrintTarget target = this.targets[i];
      return this.isUnraisedSlope(i, live)
         ? false
         : this.rules.isFinished(target, live)
            || this.clockAllowsState(target.pos(), live)
            || !this.machineOutcomes.isEmpty()
               && this.machineOutcomes.containsKey(target.pos().asLong())
               && this.rules.acceptsUnpoweredOutput(target, live);
   }

   private void recordProgress(int i, int before) {
      long now = this.env.currentTick();
      this.lastProgressTick = now;
      if (this.cellStates[i] == 3) {
         this.witnessCache.read(i);
         this.witnessMisses.load(i);
      }

      if (this.cellProgressTick != null) {
         this.cellProgressTick[i] = now;
      }

      boolean firstPlacement = (this.progressFlags[i] & 1) == 0;
      boolean firstCompletion = this.cellStates[i] == 3 && (this.progressFlags[i] & 2) == 0;
      if (this.dispatchedJobCells.remove(i)) {
         PrintMachineJob job = this.machineJobs.get(this.targets[i].pos().asLong());
         if (job != null && job.b_()) {
            this.jobBlocksPlaced.add(job.position().asLong());
         }
      }

      this.progressFlags[i] = (byte)(this.progressFlags[i] | (this.cellStates[i] == 3 ? 3 : 1));
      if (this.constructionStartTick >= 0L && (firstPlacement || firstCompletion)) {
         this.milestone++;
         if (firstPlacement) {
            this.firstPlacements++;
         }

         this.lastFreshProgressTick = now;
         this.retainOrder = false;
         this.refusedCellStances.clear();
         this.open_LongOpenHashSet.clear();
         this.failedWalkStances.clear();
         this.progressRevision++;
         this.refusedPillarCells.clear();
         this.abandonedCells.clear();
         this.clutterSkipped.clear();
         this.failedRouteCells.clear();
         this.flush_LongOpenHashSet.clear();
         this.state_LongOpenHashSet.clear();
         this.cache_LongOpenHashSet.clear();
         this.heldBackCells.clear();
         this.load_LongOpenHashSet.clear();
      }
   }

   public void notifyBlockChanged(BlockPos pos, BlockState expected) {
      if (this.preparation != null) {
         if (expected != null && !expected.isAir()) {
            this.pendingNotifications.put(pos.asLong(), expected);
         }
      } else {
         this.adoptNotifiedBlock(pos, expected);
      }
   }

   public void revisitCell(BlockPos position) {
      if (this.phase == PrintCore.J.DONE && !this.env.hasChunkAt(position)) {
         this.phase = PrintCore.J.VERIFY;
         this.activity = new PrintCore.T(new autismclient.ai.print.PrintChunkWork.Inner_StreamUtil(PrintChunkWork.chunkKey(position)));
         this.reason = "Loading saved construction for cleanup";
      }
   }

   private void adoptNotifiedBlock(BlockPos pos, BlockState expected) {
      if (expected != null
         && !expected.isAir()
         && this.env.getBlockState(pos) == expected
         && !this.temporaryBlocks.containsKey(pos.asLong())) {
         int i = this.cellIndexByPos.get(pos.asLong());
         if (i >= 0 && this.rules.isFinished(this.targets[i], expected)) {
            this.env.clearPlacedBlock(pos);
         } else {
            this.temporaryBlocks.put(pos.asLong(), expected);
            this.scaffoldsPlaced++;
            this.adjustTemporaryItemCount(expected.getBlock().asItem(), 1);
            this.env.recordPlacedBlock(pos, expected);
            this.noteOriginalSupport(pos.asLong());
            this.cleanupAccess.markEntryDirty(pos.asLong());
            this.chunkWork.resetAudit();
            long chunk = PrintChunkWork.chunkKey(pos);
            if (this.activity instanceof PrintCore.T travel && travel.destination.chunkKey == chunk
               || this.activity instanceof PrintCore.ChunkLoadWaitStep waiting && waiting.destination.chunkKey == chunk) {
               this.activity = null;
            }

            if (this.phase == PrintCore.J.DONE) {
               this.phase = PrintCore.J.VERIFY;
               this.activity = null;
            }
         }
      }
   }

   public void attachRailVehicles(List<autismclient.ai.print.PrintRailVehicle.Inner_StreamUtil> vehicles) {
      for (autismclient.ai.print.PrintRailVehicle.Inner_StreamUtil vehicle : vehicles) {
         this.attachMachineJob(new PrintRailVehicle(this.env, vehicle));
      }
   }

   public void attachItemFrames(List<autismclient.ai.print.PrintItemFrame.Inner_StreamUtil> frames) {
      for (autismclient.ai.print.PrintItemFrame.Inner_StreamUtil spec : frames) {
         long key = spec.support().asLong();
         if (!this.machineJobs.containsKey(key) && !this.clockAccessJobs.containsKey(key)) {
            PrintItemFrame job = new PrintItemFrame(this.env, spec);
            this.attachMachineJob(job);
            this.view.requiredInteractFaces.put(key, spec.facing());

            for (String reason : job.skippedReasons()) {
               if (this.skipNotes.size() < 16) {
                  this.skipNotes.add(reason);
               }
            }
         } else if (this.skipNotes.size() < 16) {
            this.skipNotes.add(spec.cell().toShortString() + ": a second saved action on the block the frame hangs on");
         }
      }
   }

   public void attachMachineJob(PrintMachineJob job) {
      if (this.constructionStartTick >= 0L) {
         throw new IllegalStateException("Attach machine actions before construction starts");
      }

      if (job.item() == Items.AIR) {
         job.init(
            () -> {
               BlockPos missingHead = this.missingOpposingHead(job.position());
               return missingHead == null
                  ? null
                  : "Filling the container at "
                     + job.position().toShortString()
                     + " would activate an assembly before its opposing piston head stands at "
                     + missingHead.toShortString();
            }
         );
      }

      if (!(job instanceof PrintClockSequence clock)) {
         if (this.clockAccessJobs.containsKey(job.position().asLong())) {
            throw new IllegalArgumentException("Multiple saved actions at " + job.position().toShortString());
         }
      } else {
         for (BlockPos at : clock.accessCells()) {
            if (this.machineJobs.containsKey(at.asLong()) || this.clockAccessJobs.containsKey(at.asLong())) {
               throw new IllegalArgumentException("Multiple saved actions at " + at.toShortString());
            }
         }

         for (BlockPos at : clock.dynamicCells()) {
            if (this.clockByDynamicCell.containsKey(at.asLong())) {
               throw new IllegalArgumentException("Overlapping clocks at " + at.toShortString());
            }
         }

         for (BlockPos at : clock.accessCells()) {
            this.clockAccessJobs.put(at.asLong(), clock);
         }

         for (BlockPos at : clock.dynamicCells()) {
            this.clockByDynamicCell.put(at.asLong(), clock);
         }
      }

      if (this.machineJobs.putIfAbsent(job.position().asLong(), job) != null) {
         throw new IllegalArgumentException("Multiple saved actions at " + job.position().toShortString());
      }

      if (job.b_() && job.needsAccess()) {
         this.containerOrder.init(job);
      }
   }

   public void attachMachineOutcomes(Map<BlockPos, BlockState> expected) {
      if (this.constructionStartTick >= 0L) {
         throw new IllegalStateException("Attach machine outcomes before construction starts");
      }

      expected.forEach(
         (position, state) -> {
            long key = position.asLong();
            if (this.machineOutcomes.put(key, state) == null) {
               this.machineOutcomesByChunk.computeIfAbsent(PrintChunkWork.chunkKey(position), ignored -> new LongArrayList()).add(key);
            }

            this.outcomeChecks.add(key);
            int cell = this.cellIndexByPos.get(key);
            if (this.preparation == null
               && cell >= 0
               && this.cellStates[cell] == 2
               && this.rules.acceptsUnpoweredOutput(this.targets[cell], this.view.getBlockState(position))) {
               this.refreshCell(cell);
            }
         }
      );
   }

   BlockState machineOutcomeAt(BlockPos position) {
      return this.machineOutcomes.get(position.asLong());
   }

   private boolean clockAllowsState(BlockPos position, BlockState actual) {
      PrintClockSequence clock = this.clockByDynamicCell.get(position.asLong());
      return clock != null && clock.allowsDynamicState(position, actual);
   }

   boolean verifiedClockAllowsState(BlockPos position, BlockState actual) {
      PrintClockSequence clock = this.clockByDynamicCell.get(position.asLong());
      return clock != null
         && this.verifiedClocks.contains(clock)
         && clock.completedPhases() >= 5
         && clock.getSpec().phase(this.env::getBlockState) >= 0
         && clock.allowsDynamicState(position, actual);
   }

