   PrintMachineJob machineJobAt(int cell) {
      if (cell >= 0 && this.cellStates[cell] == 3 && !this.machineJobs.isEmpty()) {
         BlockPos at = this.targets[cell].pos();
         PrintMachineJob owner = this.clockAccessJobs.get(at.asLong());
         if (owner == null) {
            PrintMachineJob job = this.machineJobs.get(at.asLong());
            return job instanceof PrintRailVehicle vehicle && !vehicle.getSpec().railPlacement() ? null : job;
         } else if (!this.machineJobs.containsKey(owner.position().asLong())) {
            return null;
         } else {
            return this.phase == PrintCore.J.VERIFY && !owner.currentAction().position().equals(at) ? null : owner;
         }
      } else {
         return null;
      }
   }

   private void completeMachineJob(PrintMachineJob job) {
      this.containerOrder.load(job);
      this.releaseQuietInput(job);
      if (job == this.earlyFillJob) {
         this.earlyFills++;
         this.earlyFillJob = null;
      }

      this.runningMachineJob = null;
      this.machineJobs.remove(job.position().asLong());
      this.savedSlotsVerified = this.savedSlotsVerified + job.verifiedSlots();
      if (job.write_Z() && this.jobBlocksPlaced.contains(job.position().asLong())) {
         this.removedMachineJobs.put(job.position().asLong(), new PrintCore.RemovedMachineJob(job, this.temporaryBlocksRemoved));
      }

      this.removedJobCursor = null;
      if (job instanceof PrintClockSequence clock) {
         this.verifiedClocks.add(clock);
         this.clockItemsVerified = this.clockItemsVerified + clock.verifiedItems();
         this.clockPhasesDone = this.clockPhasesDone + clock.completedPhases();
      }

      this.currentMachineAction = null;
      if (job instanceof PrintRailVehicle vehicle) {
         this.railVehiclesVerified++;
         this.verifiedRailVehicles.add(vehicle);
      } else if (job instanceof PrintItemFrame) {
         this.itemFramesVerified++;
      } else {
         this.containersFilled = this.containersFilled + job.fillCount();
         int source = this.cellIndexByPos.get(job.position().asLong());
         if (source >= 0 && this.targets[source].wanted().getBlock() instanceof HopperBlock) {
            this.hoppersFilled = this.hoppersFilled + job.fillCount();
         }
      }

      this.statuses++;
      int cell = this.cellIndexByPos.get(job.position().asLong());
      if (cell >= 0) {
         this.witnessCache.read(cell);
      }

      this.logTrace("Verified " + job.description() + " at " + job.position().toShortString() + ". " + job.detail());
      job.invalidateCapacityProof();
   }

   private boolean restoreRefillableJobs() {
      boolean restored = false;

      for (int i = 0; i < 64 && this.containerOrder.load(); i++) {
         PrintMachineJob job = this.containerOrder.pollNext();
         long key = job.position().asLong();
         if (!this.machineJobs.containsKey(key)) {
            int verified = job.verifiedSlots();
            if (job.isProvenFull()) {
               this.machineJobs.put(key, job);
               this.removedMachineJobs.remove(key);
               this.savedSlotsVerified -= verified;
               this.containersFilled = this.containersFilled - job.fillCount();
               int cell = this.cellIndexByPos.get(key);
               if (cell >= 0 && this.targets[cell].wanted().getBlock() instanceof HopperBlock) {
                  this.hoppersFilled = this.hoppersFilled - job.fillCount();
               }

               if (this.quietInputs.contains(key) && this.pendingQuietInputs.add(key)) {
                  this.pendingQuietInputsByY.merge(job.position().getY(), 1, Integer::sum);
               }

               this.earlyFillsSetAside.remove(key);
               this.statuses++;
               restored = true;
               this.logTrace("machine: rechecking changed downstream capacity at " + job.position().toShortString());
            }
         }
      }

      if (restored) {
         this.runningMachineJob = null;
         this.currentMachineAction = null;
         this.earlyFillJob = null;
         this.removedJobCursor = null;
         this.activity = null;
      }

      return restored || this.containerOrder.load();
   }

   private void skipMachineJob(PrintMachineJob job) {
      this.containerOrder.init_V(job.position());
      this.releaseQuietInput(job);
      this.removedMachineJobs.remove(job.position().asLong());
      this.runningMachineJob = null;
      this.machineJobs.remove(job.position().asLong());
      this.savedSlotsVerified = this.savedSlotsVerified + job.verifiedSlots();
      this.currentMachineAction = null;
      this.containersSkipped = this.containersSkipped + job.fillCount();
      this.savedSlotsSkipped = this.savedSlotsSkipped + job.skippedSlots();

      for (String reason : job.skippedReasons()) {
         if (this.skipNotes.size() < 16) {
            this.skipNotes.add(job.position().toShortString() + ": " + reason);
         }
      }

      this.statuses++;
      int cell = this.cellIndexByPos.get(job.position().asLong());
      if (cell >= 0) {
         this.witnessCache.read(cell);
      }

      this.logTrace("Skipped " + job.description() + " at " + job.position().toShortString() + ". " + job.detail());
   }

   private PrintCore.PrintStep failUnlessEarlyFill(String reason) {
      if (this.earlyFillJob != null && this.phase == PrintCore.J.BUILD && this.pendingMachineJob == null && !this.uncertainMachineWork) {
         this.setAsideEarlyFill(reason);
         return new PrintCore.aK(1);
      } else {
         this.phase = PrintCore.J.FAILED;
         this.stopReason = this.reason = reason;
         return null;
      }
   }

