   public PrintControls stockRouteControls() {
      if (!this.stockRouteActive) {
         this.stockRouteActive = true;
         this.activity = null;
         this.accessGoalCell = this.justClimbedCell = this.solvedAccessGoal = -1;
      }

      if (!this.env.canUseFlight() && !this.refillDescent) {
         if (this.view.hypothesisCount() > 0) {
            this.view.clearHypotheses();
         }

         if (!this.observeChanges()) {
            return this.checkingChangesControls();
         }

         this.confirmDispatched();
         this.trackAim();
         if (this.supplyReturnStep != null) {
            PrintControls controls = this.supplyReturnStep.tick();
            if (controls != null && controls.digPos != null && !this.init_Z_BlockPos(controls.digPos)) {
               return null;
            }

            if (this.supplyReturnStep.isDone()) {
               this.supplyReturnStep = null;
               this.supplyReturnDone = true;
               this.stockStanceRevision = -9223372036854775808L;
            }

            if (controls != null && (controls.clickHit != null || controls.useHeldItem || controls.digPos != null || controls.swapSourceSlot >= 0)) {
               this.lastActionTick = this.env.currentTick();
            }

            return controls == null ? this.idleControls() : controls;
         } else {
            if (!this.isRestingOnGround()) {
               return this.idleControls();
            }

            BlockPos here = PrintNav.resolveStandingCell(this.view, this.feetPosition());
            long world = this.view.worldMutationRevision();
            if (this.stockStanceCell != here.asLong() || this.stockStanceRevision != world) {
               this.stockStanceCell = here.asLong();
               this.stockStanceRevision = world;
               BlockPos floor = BlockPos.containing(
                  this.env.playerMotionState().x(),
                  this.env.playerMotionState().y() - 0.001,
                  this.env.playerMotionState().z()
               );
               this.stockFloorReady = this.pop_Z_BlockPos(floor);
               if (!this.stockFloorReady) {
                  PrintNav.Inner_TaskQueue reachable = PrintNav.searchReachable(
                     this.view,
                     here,
                     this.bounds,
                     5000,
                     null,
                     this.failedRouteCells.isEmpty() ? null : this.failedRouteCells
                  );

                  for (long key : reachable.costByCell.keySet()) {
                     BlockPos footing = new BlockPos(BlockPos.getX(key), PrintView.floorInt(reachable.feetYOf(key) - 0.001), BlockPos.getZ(key));
                     if (this.pop_Z_BlockPos(footing)) {
                        this.stockFloorReady = true;
                        break;
                     }
                  }
               }
            }

            if (this.stockFloorReady) {
               this.supplyReturnSearch = null;
               this.supplyReturnDone = false;
               return this.idleControls();
            }

            if (this.supplyReturnDone) {
               return null;
            }

            if (this.supplyReturnSearch == null) {
               PrintAccess search = new PrintAccess(this, 80.0);
               this.supplyReturnSearch = search.init_StreamUtil_ConfigS_BlockPos_D(here, this.env.playerMotionState().y());
            }

            this.reason = "Returning to ground for supplies";
            long started = System.nanoTime();
            PrintAccess.Inner_TaskQueue state = this.isBudgetSpent() ? PrintAccess.Inner_TaskQueue.SEARCHING : this.supplyReturnSearch.init(this.workBudget());
            long spent = System.nanoTime() - started;
            this.planNanos += spent;
            this.accessNanos += spent;
            this.maxDecisionNanos = Math.max(this.maxDecisionNanos, spent);
            if (state == PrintAccess.Inner_TaskQueue.INVALIDATED) {
               this.supplyReturnSearch = null;
               this.stockStanceRevision = -9223372036854775808L;
            } else {
               if (state == PrintAccess.Inner_TaskQueue.EXHAUSTED) {
                  return null;
               }

               if (state == PrintAccess.Inner_TaskQueue.FOUND) {
                  PrintAccess.Inner_BufferHelper plan = this.supplyReturnSearch.getPlan();
                  this.supplyReturnSearch = null;
                  this.supplyReturnStep = new PrintCore.AccessPlanStep(plan, null);
                  this.logTrace("supply return: " + plan.steps().size() + " native steps, no new temporary blocks");
               }
            }

            return this.idleControls();
         }
      } else {
         PrintControls controls = this.refillHereControls();
         if (controls != null && this.isRestingOnGround()) {
            this.stockFloorReady = true;
            this.stockStanceCell = PrintNav.resolveStandingCell(this.view, this.feetPosition()).asLong();
            this.stockStanceRevision = this.view.worldMutationRevision();
         }

         return controls;
      }
   }

