   public Set<Long> constructionCells() {
      if (this.isPreparing()) {
         throw new IllegalStateException("Schematic source preparation is still running");
      }

      HashSet<Long> construction = new HashSet<>();

      for (long key : this.temporaryBlocks.keySet()) {
         if (!this.cellIndexByPos.containsKey(key)) {
            construction.add(key);
         }
      }

      for (long key : this.pendingTemporary.keySet()) {
         if (!this.cellIndexByPos.containsKey(key)) {
            construction.add(key);
         }
      }

      final Set<Long> owned = Set.copyOf(construction);
      return Collections.unmodifiableSet(new AbstractSet<Long>() {
         @Override
         public boolean contains(Object key) {
            return key instanceof Long value && (PrintCore.this.cellIndexByPos.containsKey(value) || owned.contains(value));
         }

         @Override
         public boolean isEmpty() {
            return PrintCore.this.cellIndexByPos.isEmpty() && owned.isEmpty();
         }

         @Override
         public int size() {
            return PrintCore.this.cellIndexByPos.size() + owned.size();
         }

         @Override
         public Iterator<Long> iterator() {
            return Stream.concat(PrintCore.this.cellIndexByPos.keySet().stream(), owned.stream()).iterator();
         }
      });
   }

