   private static long latestBucketRevision(Long2LongOpenHashMap buckets, BlockPos c, int h0, int h1, int v0, int v1) {
      long latest = 0L;
      int x0 = c.getX() + h0 >> 2;
      int x1 = c.getX() + h1 >> 2;
      int y0 = c.getY() + v0 >> 2;
      int y1 = c.getY() + v1 >> 2;
      int z0 = c.getZ() + h0 >> 2;
      int z1 = c.getZ() + h1 >> 2;

      for (int x = x0; x <= x1; x++) {
         for (int y = y0; y <= y1; y++) {
            for (int z = z0; z <= z1; z++) {
               latest = Math.max(latest, buckets.get(BlockPos.asLong(x, y, z)));
            }
         }
      }

      return latest;
   }

