   private boolean init_Z_I_J(int i, long blocked) {
      BlockPos p = this.targets[i].pos();
      PrintCore.aM own = this.witnessCache.witness(i);
      if (own != null
         && own != NO_WITNESS
         && own.future().isEmpty()
         && !this.view.hasHypothesisAt(p)
         && (blocked == -9223372036854775808L || !own.touches(blocked))
         && own.viable(this)) {
         return true;
      }

      if (this.env.canUseFlight()) {
         BlockPos filter = this.stanceFilter;
         this.stanceFilter = null;

         try {
            return this.findWitness(i, blocked) != null;
         } finally {
            this.stanceFilter = filter;
         }
      } else {
         PrintCore.ClickReachCacheKey memo = this.clickReachCache.get(i);
         long local = this.nearbyBucketRevision(p);
         long signature = reachSignatureNear(this.reachable, p);
         if (memo == null
            || memo.blocked() != blocked
            || memo.reachSignature() != signature
            || !this.view.matchesHypothesesNear(memo.assumptions(), p, 8)
            || memo.local() != local && (memo.clickable() || !this.unchangedSince(p, memo.revision()))) {
            BlockPos filter = this.stanceFilter;
            this.stanceFilter = null;

            boolean clickable;
            try {
               clickable = this.findWitness(i, blocked) != null;
            } finally {
               this.stanceFilter = filter;
            }

            Long2ObjectOpenHashMap assumptions = new Long2ObjectOpenHashMap();
            this.view.copyHypothesesInto(assumptions);
            if (this.clickReachCache.size() >= 16384) {
               this.clickReachCache.clear();
            }

            this.clickReachCache
               .put(i, new PrintCore.ClickReachCacheKey(clickable, this.view.worldMutationRevision(), local, signature, assumptions, blocked));
            return clickable;
         } else {
            return memo.clickable();
         }
      }
   }

