   private boolean set(BlockPos here) {
      autismclient.ai.print.PrintClicks.Inner_DataUtil budget = new autismclient.ai.print.PrintClicks.Inner_DataUtil(6000);
      int own = this.cellIndexByPos.get(here.asLong());
      if (own >= 0 && this.cellStates[own] == 0 && this.push_Z_I(own)) {
         return true;
      }

      double feetY = this.view.standingHeightAt(here.getX(), here.getY(), here.getZ());
      if (Double.isNaN(feetY)) {
         return true;
      }

      List<Vec3> points = PrintClicks.getCandidateFeetPositions(this.view, here.asLong(), feetY);

      for (int dx = -5; dx <= 5; dx++) {
         for (int dz = -5; dz <= 5; dz++) {
            for (int dy = 0; dy <= 8; dy++) {
               int i = this.cellIndexByPos.get(BlockPos.asLong(here.getX() + dx, here.getY() + dy, here.getZ() + dz));
               if (i >= 0 && this.cellStates[i] == 0 && this.get(i) && !this.isOutOfReach(i)) {
                  return true;
               }
            }
         }
      }

      for (int dx = -5; dx <= 5; dx++) {
         for (int dz = -5; dz <= 5; dz++) {
            for (int dy = -5; dy <= 4; dy++) {
               int i = this.cellIndexByPos.get(BlockPos.asLong(here.getX() + dx, here.getY() + dy, here.getZ() + dz));
               if (i >= 0
                  && this.cellStates[i] == 0
                  && this.get(i)
                  && (!this.heldBackCells.contains(i) || !this.hasUnownedTemporaryBelow(this.targets[i].pos()))) {
                  for (Vec3 feet : points) {
                     if (PrintClicks.findClick(
                           this.view,
                           this.env,
                           this.rules,
                           this.targets[i],
                           this.targets[i].item(),
                           PrintClicks.Inner_CachePool.PLACE,
                           feet,
                           true,
                           false,
                           budget,
                           4.1000000000000005,
                           this.constraintFor(i)
                        )
                        != null) {
                        return true;
                     }
                  }

                  if (budget.isExhausted()) {
                     return true;
                  }
               }
            }
         }
      }

      return false;
   }

   boolean update_Z_BlockPos(BlockPos block) {
      BlockPos floor = this.floorBelow(block);
      return floor != null && this.close(block, floor);
   }

   BlockPos floorBelow(BlockPos block) {
      for (int k = 1; k <= 3; k++) {
         BlockPos below = block.below(k);
         BlockState s = this.view.getBlockState(below);
         if (s == PrintView.UNLOADED_SENTINEL
            || PrintView.isHazardBlock(s)
            || !s.getFluidState().isEmpty() && !s.getFluidState().getType().isSame(Fluids.WATER)) {
            return null;
         }

         if (!this.view.getCollisionShape(below).isEmpty()) {
            double top = centerTop(this.view.getCollisionShape(below));
            if (!Double.isNaN(top)) {
               if (top + below.getY() < block.getY() - 2.0) {
                  return null;
               }

               return below;
            }
         }
      }

      return null;
   }

   static double centerTop(VoxelShape shape) {
      double lo = 0.2;
      double hi = 0.8;
      double top = 0.0 / 0.0;

      for (AABB box : shape.toAabbs()) {
         if (box.maxX > lo && box.minX < hi && box.maxZ > lo && box.minZ < hi && !(box.maxY <= top)) {
            top = box.maxY;
         }
      }

      return top;
   }

   private boolean close(BlockPos dug, BlockPos floor) {
      if (this.temporaryBlocks.containsKey(floor.asLong())) {
         return true;
      }

      BlockPos land = floor.above();
      this.view.pushHypothesis(dug, Blocks.AIR.defaultBlockState());

      try {
         return PrintNav.searchReachable(this.view, land, this.bounds, 64, null).reachableCount() > 1
            ? true
            : this.init_Z_I_2(land.getX(), land.getY(), land.getZ()) && this.view.isPassableCell(land.above()) && this.view.isPassableCell(land.above(2));
      } finally {
         this.view.popHypothesis(dug);
      }
   }

   boolean isOpenTargetCell(BlockPos p) {
      int i = this.cellIndexByPos.get(p.asLong());
      return i >= 0 && this.cellStates[i] != 3 && this.cellStates[i] != 5;
   }

   boolean hasUnownedTemporaryBelow(BlockPos p) {
      for (int k = 1; k <= 3; k++) {
         BlockPos q = p.below(k);
         long key = q.asLong();
         if (this.temporaryBlocks.containsKey(key) && !this.temporaryOwner.containsKey(key)) {
            return true;
         }

         if (!this.view.getCollisionShape(q).isEmpty()) {
            return false;
         }
      }

      return false;
   }

   void setTemporaryOwner(long key, int owner) {
      this.temporaryOwner.put(key, owner);
      this.cleanupAccess.init(key, owner);
   }

   private int clearTemporaryOwner(long key) {
      int owner = this.temporaryOwner.remove(key);
      if (!this.temporaryBlocks.containsKey(key) && !this.pendingTemporary.containsKey(key)) {
         this.cleanupAccess.load(key);
      }

      return owner;
   }

   boolean ownerStillOpen(long key) {
      if (!this.temporaryOwner.containsKey(key)) {
         return false;
      }

      int goal = this.temporaryOwner.get(key);
      return goal >= 0 && goal < this.cellStates.length && (this.cellStates[goal] == 0 || this.cellStates[goal] == 1);
   }

