   private boolean read_Z_NodeWalker_StreamU(autismclient.ai.engine.AiPhysics.MotionState body) {
      double r = 0.299;

      for (int x = PrintView.floorInt(body.x() - r); x <= PrintView.floorInt(body.x() + r); x++) {
         for (int z = PrintView.floorInt(body.z() - r); z <= PrintView.floorInt(body.z() + r); z++) {
            for (int y = PrintView.floorInt(body.y() - 0.01); y <= PrintView.floorInt(body.y() + 1.5 - 0.001); y++) {
               BlockState state = this.view.getBlockState(new BlockPos(x, y, z));
               if (state == PrintView.UNLOADED_SENTINEL || PrintView.isHazardBlock(state) || !state.getFluidState().isEmpty()) {
                  return false;
               }
            }
         }
      }

      return true;
   }

   boolean close_Z_BlockPos(BlockPos support) {
      for (Direction d : Direction.values()) {
         if (this.load_Z_BlockPos_BlockPos(support, support.relative(d))) {
            return true;
         }
      }

      return false;
   }

   boolean open_Z_BlockPos(BlockPos p) {
      BlockState s = this.view.getBlockState(p);
      if (s.isAir() || s == PrintView.UNLOADED_SENTINEL || !s.getFluidState().isEmpty() || s.getDestroySpeed(this.view, p) < 0.0F) {
         return false;
      }

      if (!s.hasBlockEntity()
         && !s.isSignalSource()
         && !isPowerActivated(s.getBlock())
         && !(s.getBlock() instanceof FallingBlock)
         && !PrintView.isHazardBlock(s)) {
         long key = p.asLong();
         boolean temp = this.temporaryBlocks.containsKey(key) || this.view.isOwnedTemporaryAt(p);
         if (!temp) {
            int i = this.cellIndexByPos.get(key);
            if (i < 0) {
               return false;
            }

            PrintTarget t = this.targets[i];
            boolean stray = t.wanted().isAir();
            if (!stray
               && (
                  t.kind() != autismclient.ai.print.PrintTarget.Inner_DataUtil.PLACE
                     || this.cellStates[i] != 3
                     || t.item() == null
                     || t.item() == Items.AIR
                     || t.wanted().hasBlockEntity()
                     || t.wanted().isSignalSource()
                     || isPowerActivated(t.wanted().getBlock())
               )) {
               return false;
            }
         }

         for (Direction d : Direction.values()) {
            BlockState n = this.view.getBlockState(p.relative(d));
            if (!n.getFluidState().isEmpty()) {
               return false;
            }

            if (d == Direction.UP && n.getBlock() instanceof FallingBlock) {
               return false;
            }
         }

         for (Direction d : Direction.values()) {
            BlockPos np = p.relative(d);
            BlockState n = this.view.getBlockState(np);
            if (!n.isAir() && n != PrintView.UNLOADED_SENTINEL && !n.isCollisionShapeFullBlock(this.view, np)) {
               Class<?> type = n.getBlock().getClass();
               if (type != TrapDoorBlock.class && type != BedBlock.class) {
                  return false;
               }
            }
         }

         return true;
      } else {
         return false;
      }
   }

   boolean hasSolidNeighborAt(BlockPos p) {
      for (Direction d : Direction.values()) {
         BlockState s = this.view.getBlockState(p.relative(d));
         if (!s.isAir() && s != PrintView.UNLOADED_SENTINEL && !s.canBeReplaced()) {
            return false;
         }
      }

      return true;
   }

   private boolean open(BlockPos c, BlockPos except) {
      for (Direction e : Direction.values()) {
         BlockPos m = c.relative(e);
         if (!m.equals(except)) {
            BlockState ms = this.view.getBlockState(m);
            if (!ms.isAir() && ms != PrintView.UNLOADED_SENTINEL && !ms.canBeReplaced()) {
               return true;
            }
         }
      }

      return false;
   }

   private PrintCore.PrintStep ownedTemporaryCleanupStep(PrintNav.Inner_TaskQueue reach) {
      for (it.unimi.dsi.fastutil.longs.Long2IntMap.Entry e : this.temporaryOwner.long2IntEntrySet()) {
         long key = e.getLongKey();
         int cell = e.getIntValue();
         if (this.temporaryBlocks.containsKey(key) && !this.sync_Z_J(key) && this.cellStates[cell] != 0 && this.cellStates[cell] != 1) {
            PrintCore.PrintStep dig = this.digStep(reach, BlockPos.of(key), "support");
            if (dig != null) {
               return dig;
            }
         }
      }

      if (this.flightReturnPending && this.env.isFlightPermitted() && !this.groundWorkCells.isEmpty()) {
         return null;
      }

      for (it.unimi.dsi.fastutil.longs.Long2IntMap.Entry e : this.temporaryOwner.long2IntEntrySet()) {
         long key = e.getLongKey();
         if (this.temporaryBlocks.containsKey(key)
            && !this.sync_Z_J(key)
            && this.cellStates[e.getIntValue()] != 0
            && this.cellStates[e.getIntValue()] != 1) {
            BlockPos p = BlockPos.of(key);
            if (this.run(p) && this.update_Z_BlockPos(p) && this.write_Z_BlockPos_BlockPos(p, p)) {
               return new PrintCore.StreamGate(p, true);
            }

            PrintCore.PrintStep fold = this.doorSupportStep(reach, p, e.getIntValue());
            if (fold != null) {
               return fold;
            }

            PrintCore.PrintStep access = this.approachStep(
               PrintNav.resolveStandingCell(this.view, this.feetPosition()), p, "completed support"
            );
            if (access != null) {
               return access;
            }
         }
      }

      return null;
   }

   private PrintCore.PrintStep doorSupportStep(PrintNav.Inner_TaskQueue reach, BlockPos support, int owner) {
      PrintTarget door = this.targets[owner];
      BlockState open = door.wanted();
      if (!this.env.canUseFlight()
         && door.pos().distManhattan(support) == 1
         && door.pos().getY() == support.getY()
         && !this.data_LongOpenHashSet.contains(support.asLong())
         && open.getBlock().getClass() == TrapDoorBlock.class
         && !open.is(Blocks.IRON_TRAPDOOR)
         && open.getValue(BlockStateProperties.OPEN)
         && !open.getValue(BlockStateProperties.POWERED)
         && !open.getValue(BlockStateProperties.WATERLOGGED)
         && this.poll(door.pos(), support)) {
         PrintTarget closed = new PrintTarget(
            -1, door.pos(), open.setValue(BlockStateProperties.OPEN, false), autismclient.ai.print.PrintTarget.Inner_DataUtil.PLACE, Items.AIR, null
         );
         boolean firstOpen = this.cellStates[owner] == 2 && this.view.getBlockState(door.pos()) == closed.wanted();
         if (firstOpen || this.cellStates[owner] == 3 && this.view.getBlockState(door.pos()) == open) {
            BlockState state = this.temporaryBlocks.get(support.asLong());
            PrintTarget probe = new PrintTarget(-1, support, state, autismclient.ai.print.PrintTarget.Inner_DataUtil.PLACE, Items.AIR, null);
            PrintCore.t search = new PrintCore.t(this.view.worldMutationRevision(), reach.startKey);
            return search.equals(this.pop_Long2ObjectOpenHas.get(support.asLong())) ? null : new PrintCore.ad(reach, owner, closed, probe, search, firstOpen);
         } else {
            return null;
         }
      } else {
         return null;
      }
   }

