   private boolean init_Z_ListPool(PrintTarget open, PrintTarget closed, PrintTarget support, long key, Vec3 point, autismclient.ai.print.PrintClicks.Inner_DataUtil budget) {
      AABB upright = PrintGeometry.init(point.x, point.y, point.z, false);
      boolean alreadyClosed = this.view.getBlockState(open.pos()) == closed.wanted();
      if (this.view.isBoxClear(upright.deflate(0.001))
         && !this.view.intersectsHazard(upright)
         && (
            alreadyClosed
               || PrintClicks.findClick(
                     this.view,
                     this.env,
                     this.rules,
                     closed,
                     Items.AIR,
                     PrintClicks.Inner_CachePool.INTERACT,
                     point,
                     false,
                     true,
                     budget,
                     4.1000000000000005
                  )
                  != null
         )) {
         this.view.pushHypothesis(open.pos(), closed.wanted());

         try {
            if (!this.init_Z_Vec3(point)
               || PrintClicks.findClick(
                     this.view,
                     this.env,
                     this.rules,
                     support,
                     Items.AIR,
                     PrintClicks.Inner_CachePool.DIG,
                     point,
                     true,
                     true,
                     budget,
                     4.1000000000000005
                  )
                  == null) {
               return false;
            }

            this.view.pushHypothesis(support.pos(), Blocks.AIR.defaultBlockState());

            try {
               if (!this.init_Z_Vec3(point)
                  || PrintClicks.findClick(
                        this.view,
                        this.env,
                        this.rules,
                        open,
                        Items.AIR,
                        PrintClicks.Inner_CachePool.INTERACT,
                        point,
                        false,
                        true,
                        budget,
                        4.1000000000000005
                     )
                     == null) {
                  return false;
               }
            } finally {
               this.view.popHypothesis(support.pos());
            }

            if (!this.write_Z_BlockPos_BlockPos(BlockPos.of(key), support.pos())) {
               return false;
            }
         } finally {
            this.view.popHypothesis(open.pos());
         }

         if (!alreadyClosed) {
            return this.write_Z_BlockPos_BlockPos(BlockPos.of(key), support.pos());
         }

         this.view.pushHypothesis(open.pos(), open.wanted());

         try {
            return this.write_Z_BlockPos_BlockPos(BlockPos.of(key), support.pos());
         } finally {
            this.view.popHypothesis(open.pos());
         }
      } else {
         return false;
      }
   }

   private boolean init_Z_Vec3(Vec3 point) {
      if (this.view.supportAreaAtPoint(point.x, point.z, point.y) < 0.03) {
         return false;
      }

      autismclient.ai.engine.AiPhysics.MotionState body = autismclient.ai.engine.AiPhysics.MotionState.standing(point.x, point.y, point.z);
      autismclient.ai.engine.AiPhysics.MotionState next = autismclient.ai.engine.AiPhysics.stepCompat(
         body, PrintMover.init(autismclient.ai.print.PrintMover.Inner_StreamUtil.NONE, 0.0F), this.view.asPhysicsWorld()
      );
      return next.onGround() && next.position().distanceToSqr(point) < 1.0E-6 && !this.view.intersectsHazard(next.box(false));
   }

