   private PrintCore.PrintStep buriedCleanupStep(PrintNav.Inner_TaskQueue reach, BlockPos here) {
      LongIterator it = this.cleanupCandidates.iterator();

      while (it.hasNext()) {
         long key = it.nextLong();
         if (!this.temporaryBlocks.containsKey(key)) {
            it.remove();
         } else if (!this.digAttempted.contains(key)) {
            PrintCore.PrintStep dig = this.digStep(reach, BlockPos.of(key), "buried");
            if (dig != null) {
               this.stallCount = 0;
               return dig;
            }
         }
      }

      for (long key : this.cleanupCandidates) {
         PrintCore.PrintStep climb = this.approachStep(here, BlockPos.of(key), "buried");
         if (climb != null) {
            this.stallCount = 0;
            return climb;
         }
      }

      return null;
   }

   private PrintCore.PrintStep digStep(PrintNav.Inner_TaskQueue reach, BlockPos p, String why) {
      long key = p.asLong();
      if (this.sync_Z_J(key)) {
         return null;
      }

      PrintTarget probe = new PrintTarget(-1, p, this.view.getBlockState(p), autismclient.ai.print.PrintTarget.Inner_DataUtil.PLACE, Items.AIR, null);
      autismclient.ai.print.PrintClicks.Inner_DataUtil budget = new autismclient.ai.print.PrintClicks.Inner_DataUtil(6000);
      LongArrayList candidates = new LongArrayList();

      for (int dx = -4; dx <= 4; dx++) {
         for (int dz = -4; dz <= 4; dz++) {
            for (int dy = -4; dy <= 5; dy++) {
               long sk = BlockPos.asLong(p.getX() + dx, p.getY() + dy, p.getZ() + dz);
               if (reach.isReachable(sk)) {
                  candidates.add(sk);
               }
            }
         }
      }

      candidates.sort((a, b) -> Double.compare(reach.costOf(a), reach.costOf(b)));

      for (long sk : candidates) {
         if (reach.isReachable(sk)
            && (sk == reach.startKey || !this.failedWalkStances.contains(sk))
            && !this.failedDigStances.contains(cellStanceKey((int)(key & 2147483647L), sk))
            && this.hasWayOut(reach, sk)
            && sk != BlockPos.asLong(p.getX(), p.getY() + 1, p.getZ())) {
            autismclient.ai.print.PrintClicks.Inner_StreamUtil click = this.findClickAt(reach, sk, probe, budget);
            if (click != null) {
               boolean keepDown = this.isAboveBase(BlockPos.of(sk)) && (this.push_Z() || p.distChessboard(BlockPos.of(sk)) <= 8);
               if (keepDown ? this.write_Z_BlockPos_BlockPos(BlockPos.of(sk), p) : this.canEscapeAfterDig(BlockPos.of(sk), p)) {
                  this.logTrace(why + ": digging out " + p.toShortString());
                  PrintCore.PrintStep dig = new PrintCore.StreamGate(p, false, sk, click.crouch(), click.feet());
                  return sk == reach.startKey ? dig : new PrintCore.aL(reach.reconstructPath(sk), reach, dig);
               }
            }
         }
      }

      return null;
   }

   private void logNoClick(PrintNav.Inner_TaskQueue reach, int i) {
      if (this.env.currentTick() - this.noClickLoggedTick.getOrDefault(i, -4611686018427387904L) >= 400L) {
         this.noClickLoggedTick.put(i, this.env.currentTick());
         PrintTarget t = this.targets[i];
         BlockPos c = t.pos();
         StringBuilder out = new StringBuilder("no click for " + c.toShortString() + " (" + this.view.getBlockState(c) + "):");
         int shown = 0;

         for (int dx = -4; dx <= 4 && shown < 8; dx++) {
            for (int dz = -4; dz <= 4 && shown < 8; dz++) {
               for (int dy = -5; dy <= 3 && shown < 8; dy++) {
                  long key = BlockPos.asLong(c.getX() + dx, c.getY() + dy, c.getZ() + dz);
                  if (reach.isReachable(key)) {
                     String flags = (this.refusedCellStances.contains(cellStanceKey(i, key)) ? "P" : "")
                        + (this.failedWalkStances.contains(key) ? "S" : "")
                        + (isBodyCell(key, c) ? "B" : "");
                     Vec3 feet = PrintNav.cellCenterAtY(key, reach.feetYOf(key));
                     autismclient.ai.print.PrintClicks.Inner_StreamUtil geo = PrintClicks.findClick(
                        this.view,
                        this.env,
                        this.rules,
                        t,
                        t.item(),
                        PrintClicks.Inner_CachePool.PLACE,
                        feet,
                        true,
                        false,
                        new autismclient.ai.print.PrintClicks.Inner_DataUtil(4000),
                        4.1000000000000005,
                        this.constraintFor(i)
                     );
                     if (geo != null || !flags.isEmpty()) {
                        String exact = "-";
                        if (geo != null) {
                           BlockState got = this.env.predictPlacedState(t.item(), geo.result(), geo.yaw(), geo.pitch(), true, c);
                           exact = got == null ? "refused" : (this.rules.isPlacedCorrectly(t, got) ? "ok" : String.valueOf(got));
                        }

                        out.append(' ')
                           .append(BlockPos.of(key).toShortString())
                           .append('[')
                           .append(flags)
                           .append("] geo ")
                           .append(geo == null ? "none" : geo.support().toShortString() + " " + geo.face())
                           .append(" vanilla ")
                           .append(exact)
                           .append(';');
                        shown++;
                     }
                  }
               }
            }
         }

         if (shown == 0) {
            out.append(" no stance in reach has even a geometric click");
         }

         this.logTrace(out.toString());
      }
   }

   private PrintCore.PrintStep clutterStep(PrintNav.Inner_TaskQueue reach, IntArrayList frontier) {
      for (int i : frontier) {
         PrintTarget t = this.targets[i];
         if (t.kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.PLACE && !this.clutterSkipped.contains(t.pos().asLong())) {
            BlockState here = this.view.getBlockState(t.pos());
            if (!here.isAir()
               && here != PrintView.UNLOADED_SENTINEL
               && here.getFluidState().isEmpty()
               && !this.temporaryBlocks.containsKey(t.pos().asLong())) {
               boolean clutter = here.canBeReplaced() && !here.getShape(this.view, t.pos()).isEmpty();
               boolean wrong = !here.canBeReplaced()
                  && !this.rules.isPlacedCorrectly(t, here)
                  && !this.rules.isFinished(t, here);
               if (clutter || wrong) {
                  String why = (wrong ? "wrong block " + here.getBlock().getName().getString() : "clutter") + " in " + t.pos().toShortString();
                  PrintCore.PrintStep dig = this.digStep(reach, t.pos(), why);
                  if (dig != null) {
                     return dig;
                  }

                  if (wrong) {
                     PrintCore.PrintStep climb = this.approachStep(BlockPos.of(reach.startKey), t.pos(), why);
                     if (climb != null) {
                        this.logTrace(why + ": no stance in reach digs it; planning a climb");
                        return climb;
                     }

                     this.logTrace(why + ": no stance digs it");
                  }

                  this.clutterSkipped.add(t.pos().asLong());
               }
            }
         }
      }

      return null;
   }

