   private boolean init_Z_I(int x, int y0, int z, int depth) {
      int k = 1;

      while (k <= depth) {
         BlockPos p = new BlockPos(x, y0 - k, z);
         if (this.cellIndexByPos.get(p.asLong()) < 0 && !this.temporaryBlocks.containsKey(p.asLong())) {
            BlockState st = this.view.getBlockState(p);
            if (st != PrintView.UNLOADED_SENTINEL && !st.isAir() && !(st.getDestroySpeed(this.view, p) < 0.0F) && st.getFluidState().isEmpty()) {
               for (Direction d : Direction.values()) {
                  if (!this.view.getBlockState(p.relative(d)).getFluidState().isEmpty()) {
                     return false;
                  }
               }

               k++;
               continue;
            }

            return false;
         }

         return false;
      }

      BlockPos floor = new BlockPos(x, y0 - depth - 1, z);
      return this.view.getBlockState(floor).isFaceSturdy(this.view, floor, Direction.UP);
   }

