   private PrintCore.PrintStep climbToCells(BlockPos here, IntArrayList goals, Item temp) {
      autismclient.ai.engine.AiPhysics.MotionState body = this.env.playerMotionState();
      if (goals.isEmpty()) {
         this.logTrace("access: no cells to climb to");
         return null;
      }

      BlockState tempState = defaultStateOf(temp);
      double feetY = this.view.standingHeightAt(here.getX(), here.getY(), here.getZ());
      if (Double.isNaN(feetY)) {
         feetY = body.y();
      }

      long goalSig = 0L;

      for (int g : goals) {
         goalSig = goalSig * 31L + g;
      }

      if (temp == Items.GLASS) {
         goalSig ^= 3406871041633115229L;
      }

      long sig = here.asLong() * 1000003L + goalSig;
      long world = this.view.worldMutationRevision();
      PrintCore.RetryRecord known = this.retryRecords.get(goalSig);
      if (known != null && (sig == known.sig || known.exhausted) && (world == known.world || this.env.currentTick() - known.tick < known.retry)) {
         this.noWorkReason = "no access to the lowest waiting cells";
         this.logTrace(
            "access: "
               + goals.size()
               + " cells from "
               + this.targets[goals.getInt(0)].pos().toShortString()
               + " failed before ("
               + (known.exhausted ? "exhausted" : "same stance")
               + ", "
               + (this.env.currentTick() - known.tick)
               + " ticks ago)"
         );
         return null;
      } else {
         return new PrintCore.Q(here, feetY, goals, tempState, temp, goalSig, sig, world);
      }
   }

   int init_I_IntArrayList(IntArrayList goals) {
      if (this.threatenedCells.isEmpty()) {
         return -1;
      }

      int limit = 64;
      IntLinkedOpenHashSet pending = new IntLinkedOpenHashSet(64);
      IntListIterator roots = this.threatenedCells.iterator();

      for (int count = 0; count < 16 && roots.hasNext(); count++) {
         pending.add(roots.nextInt());
      }

      IntOpenHashSet visited = new IntOpenHashSet(64);
      int edges = 0;

      while (!pending.isEmpty() && visited.size() < 64) {
         int cell = pending.removeFirstInt();
         if (visited.add(cell) && this.cellStates[cell] != 3 && this.cellStates[cell] != 5) {
            if (goals.contains(cell)) {
               return cell;
            }

            PrintTarget target = this.targets[cell];
            if (restsOnFloor(target.wanted()) || this.size(cell)) {
               int below = this.cellIndexByPos.get(target.pos().below().asLong());
               if (below >= 0) {
                  pending.add(below);
               }
            }

            for (int[] group : new int[][]{
               this.predecessorsOf(cell), this.inputCells[cell], this.unresolvedPredecessors[cell], this.observerCells[cell], this.watchedInputCells[cell]
            }) {
               for (int dependency : group) {
                  if (pending.size() >= 64 || edges++ >= 256) {
                     break;
                  }

                  if (this.cellStates[dependency] != 3 && !visited.contains(dependency)) {
                     pending.add(dependency);
                  }
               }
            }
         }
      }

      return -1;
   }

   boolean read_Z_BlockPos_BlockPos(BlockPos cell, BlockPos filled) {
      if (this.push(cell, filled)) {
         return false;
      }

      LongOpenHashSet seen = new LongOpenHashSet();
      ArrayDeque<BlockPos> queue = new ArrayDeque<>();
      seen.add(cell.asLong());
      queue.add(cell);

      while (!queue.isEmpty()) {
         BlockPos at = queue.poll();

         for (Direction d : Direction.values()) {
            BlockPos m = at.relative(d);
            if (seen.add(m.asLong())) {
               if (m.getX() < this.bounds.minX()
                  || m.getX() > this.bounds.maxX()
                  || m.getZ() < this.bounds.minZ()
                  || m.getZ() > this.bounds.maxZ()
                  || m.getY() > this.maxTargetY()) {
                  return false;
               }

               if (m.getY() >= Math.min(this.baseY - 1, cell.getY()) && this.pop(m, filled)) {
                  if (seen.size() > 2048) {
                     return false;
                  }

                  queue.add(m);
               }
            }
         }
      }

      return true;
   }

   private boolean push(BlockPos cell, BlockPos filled) {
      int top = this.maxTargetY();
      if (cell.getX() >= this.bounds.minX()
         && cell.getX() <= this.bounds.maxX()
         && cell.getZ() >= this.bounds.minZ()
         && cell.getZ() <= this.bounds.maxZ()
         && cell.getY() <= top) {
         record Inner_StreamUtil(Direction direction, int length) {
         }

         Inner_StreamUtil[] rays = new Inner_StreamUtil[]{
            new Inner_StreamUtil(Direction.WEST, cell.getX() - this.bounds.minX() + 1),
            new Inner_StreamUtil(Direction.EAST, this.bounds.maxX() - cell.getX() + 1),
            new Inner_StreamUtil(Direction.NORTH, cell.getZ() - this.bounds.minZ() + 1),
            new Inner_StreamUtil(Direction.SOUTH, this.bounds.maxZ() - cell.getZ() + 1),
            new Inner_StreamUtil(Direction.UP, top - cell.getY() + 1)
         };
         Arrays.sort(rays, Comparator.comparingInt(Inner_StreamUtil::length));
         MutableBlockPos point = new MutableBlockPos();

         for (Inner_StreamUtil ray : rays) {
            if (ray.length() <= 64) {
               for (int step = 1; step <= ray.length(); step++) {
                  point.set(
                     cell.getX() + ray.direction().getStepX() * step,
                     cell.getY() + ray.direction().getStepY() * step,
                     cell.getZ() + ray.direction().getStepZ() * step
                  );
                  if (step == ray.length()) {
                     return true;
                  }

                  if (point.getY() < Math.min(this.baseY - 1, cell.getY()) || !this.pop(point, filled)) {
                     break;
                  }
               }
            }
         }

         return false;
      } else {
         return true;
      }
   }

   private boolean pop(BlockPos m, BlockPos filled) {
      int mi = this.cellIndexByPos.get(m.asLong());
      BlockState end;
      if (m.equals(filled)) {
         end = this.targets[this.cellIndexByPos.get(filled.asLong())].wanted();
      } else if (mi >= 0) {
         if (this.targets[mi].fluid() || this.targets[mi].kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLOW) {
            return true;
         }

         end = this.targets[mi].wanted();
      } else {
         if (this.temporaryBlocks.containsKey(m.asLong()) || this.view.isOwnedTemporaryAt(m)) {
            return true;
         }

         end = this.view.getBlockState(m);
      }

      if (end == PrintView.UNLOADED_SENTINEL) {
         return true;
      } else {
         return isDoorOrGate(end) ? true : end.getCollisionShape(this.view, m).isEmpty();
      }
   }

   private PrintCore.PrintStep init_UiHelper_NetHelper_J_BlockPos(long station, BlockPos target) {
      ArrayDeque<Supplier<PrintCore.PrintStep>> parts = new ArrayDeque<>();
      parts.add(
         () -> this.phase == PrintCore.J.TEARDOWN
               && this.temporaryBlocks.containsKey(target.asLong())
               && this.update_Z_BlockPos(target)
               && PrintNav.resolveStandingCell(this.view, this.feetPosition()).asLong() == station
            ? this.removalAt(new PrintNav.Inner_TaskQueue(station), station, target, true, null)
            : null
      );
      return new PrintCore.SequentialStep(parts);
   }

   private PrintCore.PrintStep init_UiHelper_NetHelper_BlockPos(BlockPos here, double feetY, IntArrayList goals, BlockState tempState, Item temp) {
      LongOpenHashSet stances = new LongOpenHashSet();
      Long2IntOpenHashMap goalOf = new Long2IntOpenHashMap();
      int looked = 0;

      for (int g : goals) {
         if (looked++ >= 8) {
            break;
         }

         PrintCore.aM w = this.findWitness(g, -9223372036854775808L, true);
         if (w != null && w != NO_WITNESS) {
            long last = this.write_Long2LongOpenHashM.getOrDefault(w.stance(), -4611686018427387904L);
            if (this.env.currentTick() - last >= 800L) {
               stances.add(w.stance());
               goalOf.put(w.stance(), g);
            }
         }
      }

      if (stances.isEmpty()) {
         return null;
      }

      for (long k : stances) {
         this.write_Long2LongOpenHashM.put(k, this.env.currentTick());
      }

      PrintAccess search = new PrintAccess(this, 80.0);
      search.lowestGoalY = PrintAccess.lowestGoalY(this, goals);
      PrintAccess.Inner_BufferHelper plan = search.planToStances(here, feetY, stances, tempState, 20000);
      if (plan != null && !plan.steps().isEmpty()) {
         int g = goalOf.get(search.foundGoalKey);
         this.logTrace(
            "access plan (to a clicking stance): "
               + plan.steps().size()
               + " steps, "
               + plan.temps()
               + " temporary, toward "
               + this.targets[g].pos().toShortString()
               + " from "
               + BlockPos.of(search.foundGoalKey).toShortString()
               + " ("
               + describePlan(plan)
               + ")"
         );
         this.accessGoalCell = g;
         this.accessStartPlacements = this.firstPlacements;
         this.reason = "Getting into position (" + plan.steps().size() + " steps)";
         return new PrintCore.AccessPlanStep(plan, temp);
      } else {
         this.logTrace("access: no way onto " + stances.size() + " stances that click the lowest cells (" + search.failureDetail + ")");
         return null;
      }
   }

   static String describePlan(PrintAccess.Inner_BufferHelper plan) {
      StringBuilder out = new StringBuilder();

      for (PrintAccess.Inner_NetHelper st : plan.steps()) {
         if (out.length() > 0) {
            out.append(", ");
         }

         out.append(st.kind().name().charAt(0)).append(' ').append(BlockPos.of(st.to()).toShortString());
      }

      return out.toString();
   }

   private PrintCore.PrintStep exitPlanStep(BlockPos here) {
      long t0 = System.nanoTime();

      try {
         return this.planExit(here);
      } finally {
         this.exitPlanNanos = this.exitPlanNanos + (System.nanoTime() - t0);
      }
   }

   private PrintCore.PrintStep planExit(BlockPos here) {
      if (this.isWithinFootprint(here.getX(), here.getZ()) || here.getY() > this.maxTargetY()) {
         return null;
      }

      if (!this.state_LongOpenHashSet.add(here.asLong())) {
         return null;
      }

      Item temp = this.tempItem();
      BlockState tempState = temp instanceof BlockItem bi ? bi.getBlock().defaultBlockState() : null;
      double feetY = this.view.standingHeightAt(here.getX(), here.getY(), here.getZ());
      if (Double.isNaN(feetY)) {
         feetY = this.env.playerMotionState().y();
      }

      PrintAccess.Inner_BufferHelper plan = new PrintAccess(this, 80.0).planAccess(here, feetY, tempState, 20000);
      if (plan != null && !plan.steps().isEmpty()) {
         this.logTrace(
            "exit plan: "
               + plan.steps().size()
               + " steps, "
               + plan.temps()
               + " temporary, cost "
               + (int)plan.cost()
               + " ("
               + describePlan(plan)
               + ")"
         );
         this.reason = "Getting out (" + plan.steps().size() + " steps)";
         return new PrintCore.AccessPlanStep(plan, temp);
      } else {
         this.noWorkReason = "shut in: no way out of the schematic";
         return null;
      }
   }

   private boolean add(BlockPos p) {
      return !this.view.getCollisionShape(p).isEmpty() || !this.view.getOutlineShape(p).isEmpty();
   }

   private void breakoutDig(BlockPos p) {
      int i = this.cellIndexByPos.get(p.asLong());
      if (i >= 0 && !this.view.getBlockState(p).isAir() && !this.temporaryBlocks.containsKey(p.asLong())) {
         this.breakoutDigCells.add(p.asLong());
         this.breakoutDigs++;
      }

      this.logTrace("breakout: digging " + p.toShortString() + " (" + this.view.getBlockState(p) + ")");
   }

   boolean cellHasSolidNeighbor(int i) {
      BlockPos p = this.targets[i].pos();

      for (Direction d : Direction.values()) {
         BlockState s = this.view.getBlockState(p.relative(d));
         if (!s.isAir() && s != PrintView.UNLOADED_SENTINEL && !s.canBeReplaced()) {
            return true;
         }
      }

      return false;
   }

   boolean push_Z_I(int i) {
      if (this.rideCompatible[i] != 0) {
         return this.rideCompatible[i] > 0;
      }

      PrintTarget t = this.targets[i];
      boolean ok = t.kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.PLACE
         && t.wanted().isCollisionShapeFullBlock(this.view, t.pos())
         && this.rules.nextInteraction(t, t.wanted()) == null
         && AiPrintRules.placeableFromAbove(t)
         && !(t.wanted().getBlock() instanceof FallingBlock);
      this.rideCompatible[i] = (byte)(ok ? 1 : -1);
      return ok;
   }

   private static BlockState defaultStateOf(Item item) {
      return item instanceof BlockItem block ? block.getBlock().defaultBlockState() : null;
   }

   Item tempItem() {
      return this.tempItemAvoiding(Set.of());
   }

   private Item tempItemAvoiding(Set<Item> avoid) {
      if (!avoid.contains(Items.DIRT) && this.inventoryCount(Items.DIRT) > 0) {
         return Items.DIRT;
      }

      autismclient.ai.print.PrintTools.Inner_DataUtil choice = PrintTools.init(
         this.env, this.targetItems, this::inventoryCount, this.openCountByItem::getInt, avoid
      );
      if (choice != null) {
         return choice.item();
      }

      if (!avoid.isEmpty()) {
         return null;
      }

      if (!this.env.isCreativeMode()) {
         this.env.requestCreativeItem(Items.DIRT);
      }

      return Items.DIRT;
   }

   Item tempItemFor(PrintTarget target) {
      return target != null && this.inventoryCount(target.item()) <= this.openCountByItem.getInt(target.item())
         ? this.tempItemAvoiding(Set.of(target.item()))
         : this.tempItem();
   }

   private Item tempItemForGoals(IntArrayList goals) {
      HashSet<Item> avoid = new HashSet<>();

      for (int goal : goals) {
         if (this.inventoryCount(this.targets[goal].item()) <= this.openCountByItem.getInt(this.targets[goal].item())) {
            avoid.add(this.targets[goal].item());
         }
      }

      return this.tempItemAvoiding(avoid);
   }

   private PrintCore.PrintStep interactionStep() {
      long t0 = System.nanoTime();

      try {
         return this.planInteraction();
      } finally {
         this.interactionNanos = this.interactionNanos + (System.nanoTime() - t0);
      }
   }

   private PrintCore.PrintStep planInteraction() {
      this.f_m_I = -1;
      autismclient.ai.engine.AiPhysics.MotionState body = this.env.playerMotionState();
      Vec3 feet = new Vec3(body.x(), body.y(), body.z());

      for (int i = this.placedCells.nextSetBit(0); i >= 0; i = this.placedCells.nextSetBit(i + 1)) {
         if (this.env.hasChunkAt(this.targets[i].pos()) && !this.run(i)) {
            PrintTarget t = this.targets[i];
            BlockState live = this.view.getBlockState(t.pos());
            PrintRules.Inner_CachePool step = this.rules.nextInteraction(t, live);
            if (step == null) {
               if (!this.rules.isWaterlogMissing(t, live) && !this.isUnraisedSlope(i, live)) {
                  this.setCellState(i, (byte)3);
               }
            } else {
               long hereKey = PrintNav.resolveStandingCell(this.view, feet).asLong();
               if (!this.env.canUseFlight() && body.onGround() && step.item() == Items.AIR && live.getBlock().getClass() == TrapDoorBlock.class) {
                  for (Direction side : Plane.HORIZONTAL) {
                     BlockPos support = t.pos().relative(side);
                     long key = support.asLong();
                     if (this.temporaryOwner.getOrDefault(key, -1) == i && this.temporaryBlocks.containsKey(key) && !this.sync_Z_J(key)) {
                        PrintNav.Inner_TaskQueue local = new PrintNav.Inner_TaskQueue(hereKey);
                        local.costByCell.put(hereKey, 0.0);
                        local.feetYByCell.put(hereKey, feet.y);
                        PrintCore.PrintStep recovery = this.doorSupportStep(local, support, i);
                        if (recovery != null) {
                           return recovery;
                        }
                     }
                  }
               }

               autismclient.ai.print.PrintClicks.Inner_StreamUtil at = null;
               if (!this.refusedCellStances.contains(cellStanceKey(i, hereKey)) && feet.distanceToSqr(PrintView.blockCenter(t.pos())) <= 36.0) {
                  at = this.findInteractionClick(t, step, feet, new autismclient.ai.print.PrintClicks.Inner_DataUtil(500));
                  if (at == null) {
                     double hereFeet = this.view.standingHeightAt(BlockPos.getX(hereKey), BlockPos.getY(hereKey), BlockPos.getZ(hereKey));
                     if (!Double.isNaN(hereFeet)) {
                        autismclient.ai.print.PrintClicks.Inner_DataUtil budget = new autismclient.ai.print.PrintClicks.Inner_DataUtil(2000);

                        for (Vec3 point : PrintClicks.getCandidateFeetPositions(this.view, hereKey, hereFeet, true)) {
                           if ((at = this.findInteractionClick(t, step, point, budget)) != null || budget.isExhausted()) {
                              break;
                           }
                        }
                     }
                  }
               }

               if (at != null) {
                  return new PrintCore.C(i, step, hereKey, at.feet(), at.crouch());
               }

               if (this.trace && feet.distanceToSqr(PrintView.blockCenter(t.pos())) <= 36.0) {
                  this.logTrace(
                     "interact: none for "
                        + t.pos().toShortString()
                        + " from "
                        + formatVec(feet)
                        + " failed "
                        + this.refusedCellStances.contains(cellStanceKey(i, hereKey))
                        + " item "
                        + step.item()
                        + " live "
                        + live
                  );
               }

               if (this.f_m_I < 0) {
                  this.f_m_I = i;
               }
            }
         }
      }

      return null;
   }

   private PrintCore.PrintStep decideFluids() {
      autismclient.ai.engine.AiPhysics.MotionState body = this.env.playerMotionState();
      BlockPos here = PrintNav.resolveStandingCell(this.view, new Vec3(body.x(), body.y(), body.z()));
      PrintCore.PrintStep slopeUndo = this.read_UiHelper_NetHelper_BlockPos(here);
      if (slopeUndo != null) {
         return slopeUndo;
      }

      boolean any = false;

      for (int i : this.fluidOrWaterlogged()) {
         PrintTarget t = this.targets[i];
         if (this.cellStates[i] != 3
            && this.cellStates[i] != 5
            && (
               t.kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLUID
                  || this.cellStates[i] == 2 && this.rules.isWaterlogMissing(t, this.view.getBlockState(t.pos()))
            )) {
            any = true;
            break;
         }
      }

      PrintCore.PrintStep undo = this.init_UiHelper_NetHelper_BlockPos_Z(here, !any);
      if (undo != null) {
         return undo;
      }

      if (this.isFluidSettling() && this.settleWaits++ < 300) {
         this.reason = "Letting the fluid settle";
         PrintCore.PrintStep chained = this.chainedFluidStep();
         return chained != null ? chained : new PrintCore.aK(1);
      }

      if (!this.isFluidSettling()) {
         this.settleWaits = 0;
      }

      if (!any) {
         this.phase = PrintCore.J.TEARDOWN;
         this.reason = "Removing temporary blocks";
         return this.decideTeardown();
      }

      PrintNav.Inner_TaskQueue reach = this.reachFrom(here);
      autismclient.ai.print.PrintClicks.Inner_DataUtil budget = new autismclient.ai.print.PrintClicks.Inner_DataUtil(40000);
      boolean holdLava = this.shouldHoldLava();

      for (int i : this.fluidWorkByHeight()) {
         PrintTarget t = this.targets[i];
         if (this.env.hasChunkAt(t.pos()) && this.cellStates[i] != 3 && this.cellStates[i] != 5) {
            PrintClicks.Inner_CachePool mode;
            if (t.kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLUID) {
               boolean lava = t.wanted().getFluidState().getType().isSame(Fluids.LAVA);
               if (lava && holdLava) {
                  continue;
               }

               mode = PrintClicks.Inner_CachePool.POUR;
               PrintCore.PrintStep preparation = this.init_UiHelper_NetHelper_TokenStore_TaskQue_I(reach, i);
               if (preparation == this.waitOneTick) {
                  continue;
               }

               if (preparation != null) {
                  return preparation;
               }

               PrintCore.PrintStep slope = this.spillShapeStep(reach, i);
               if (slope == this.waitOneTick) {
                  continue;
               }

               if (slope != null) {
                  return slope;
               }

               BlockPos spill = this.findSpill(t.pos(), t.wanted().getFluidState().getType());
               if (spill != null && this.temporaryBlocks.containsKey(spill.asLong()) && !this.ownerStillOpen(spill.asLong())) {
                  PrintCore.PrintStep dig = this.digStep(reach, spill, "holds back " + t.pos().toShortString());
                  if (dig != null) {
                     return dig;
                  }
               }

               if (spill != null) {
                  int spillCell = this.cellIndexByPos.get(spill.asLong());
                  if (GIVE_UP && spillCell >= 0 && this.cellStates[spillCell] == 5) {
                     this.giveUpCell(i, "would spill into " + spill.toShortString() + ", given up");
                  } else {
                     this.noWorkReason = "water at " + t.pos().toShortString() + " would spill into " + spill.toShortString();
                  }
                  continue;
               }

               PrintCore.PrintStep shaping = this.fallingFlowStep(reach);
               if (shaping == this.waitOneTick) {
                  continue;
               }

               if (shaping != null) {
                  return shaping;
               }

               if (this.temporaryBlocks.containsKey(t.pos().asLong())) {
                  PrintCore.PrintStep dig = this.digStep(reach, t.pos(), "pour");
                  if (dig != null) {
                     return dig;
                  }
                  continue;
               }
            } else {
               if (this.cellStates[i] != 2 || !this.rules.isWaterlogMissing(t, this.view.getBlockState(t.pos()))) {
                  continue;
               }

               mode = PrintClicks.Inner_CachePool.WATERLOG;
               this.predictFlow(t.pos(), t.wanted().getFluidState().getType());
               PrintCore.PrintStep shaping = this.fallingFlowStep(reach);
               if (shaping == this.waitOneTick) {
                  continue;
               }

               if (shaping != null) {
                  return shaping;
               }
            }

            if (!this.temporaryBlocks.isEmpty()) {
               this.predictFlow(t.pos(), t.wanted().getFluidState().getType());
            }

            PrintCore.PrintStep drain = this.wetTemporaryStep(reach);
            if (drain != this.waitOneTick) {
               if (drain != null) {
                  return drain;
               }

               Item bucket = PrintClicks.getFluidBucketItem(t);
               BlockPos c = t.pos();

               for (long key : this.stancesNear(reach, c, true)) {
                  if (!this.refusedCellStances.contains(cellStanceKey(i, key))) {
                     for (Vec3 feet : PrintClicks.getCandidateFeetPositions(this.view, key, reach.feetYOf(key))) {
                        autismclient.ai.print.PrintClicks.Inner_StreamUtil click = PrintClicks.findClick(
                           this.view,
                           this.env,
                           this.rules,
                           t,
                           bucket,
                           mode,
                           feet,
                           mode != PrintClicks.Inner_CachePool.WATERLOG,
                           false,
                           budget,
                           4.1000000000000005
                        );
                        if (click != null && this.hasWayOut(reach, key) && this.init_Z_J_ListPool(key, t)) {
                           this.reason = "Pouring " + BuiltInRegistries.ITEM.getKey(bucket).getPath();
                           this.logTrace(
                              "fluids: "
                                 + mode
                                 + " "
                                 + t.pos().toShortString()
                                 + " from "
                                 + BlockPos.of(key).toShortString()
                                 + " (body "
                                 + formatVec(this.feetPosition())
                                 + ")"
                           );
                           PrintCore.PrintStep pour = new PrintCore.aj(i, mode, key, feet);
                           return key == reach.startKey ? pour : new PrintCore.aL(reach.reconstructPath(key), reach, pour);
                        }
                     }
                  }
               }
            }
         }
      }

      if (!this.noWorkReason.startsWith("water at")) {
         this.noWorkReason = "no reachable stance pours the remaining fluids";
      }

      this.logTrace("fluids: " + this.noWorkReason + " (body " + formatVec(this.feetPosition()) + ", reach " + reach.reachableCount() + ")");
      if (this.push_Z_BlockPos(here)) {
         PrintCore.PrintStep leave = this.exitPlanStep(here);
         if (leave != null) {
            return leave;
         }
      }

      IntArrayList goals = new IntArrayList();

      for (int i : this.fluidOrWaterlogged()) {
         if (this.targets[i].kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLUID
            && this.cellStates[i] == 0
            && !this.isOutOfReach(i)
            && !this.temporaryBlocks.containsKey(this.targets[i].pos().asLong())
            && (this.spillShapeOf(i) == null || this.load_Z_UiHelper_aB(this.spillShapeOf(i)))
            && (!holdLava || !this.targets[i].wanted().getFluidState().getType().isSame(Fluids.LAVA))
            && this.findSpill(this.targets[i].pos(), this.targets[i].wanted().getFluidState().getType()) == null) {
            goals.add(i);
         } else if (this.cellStates[i] == 2
            && this.rules.isWaterlogMissing(this.targets[i], this.view.getBlockState(this.targets[i].pos()))) {
            goals.add(i);
         }
      }

      if (holdLava && (goals.isEmpty() || this.cache_LongOpenHashSet.contains(here.asLong()))) {
         this.flags_Z = true;
         return new PrintCore.aK(1);
      }

      if (!goals.isEmpty() && this.cache_LongOpenHashSet.add(here.asLong())) {
         Item temp = this.tempItemForGoals(goals);
         BlockState tempState = temp instanceof BlockItem bi ? bi.getBlock().defaultBlockState() : null;
         double feetY = this.view.standingHeightAt(here.getX(), here.getY(), here.getZ());
         if (Double.isNaN(feetY)) {
            feetY = this.env.playerMotionState().y();
         }

         return new PrintCore.ab(here, feetY, goals, tempState, temp);
      } else {
         if (++this.pourLogCounter % 40 == 0) {
            this.cache_LongOpenHashSet.clear();
            this.refusedCellStances.clear();
            this.open_LongOpenHashSet.clear();
            this.failedWalkStances.clear();
            this.progressRevision++;
         }

         if (GIVE_UP && this.env.currentTick() - this.lastProgressTick >= 250L) {
            int n = 0;

            for (int i : this.fluidOrWaterlogged()) {
               if (this.targets[i].kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLUID && this.cellStates[i] == 0) {
                  this.giveUpCell(i, "fluids stuck: " + this.noWorkReason);
                  n++;
               } else if (this.cellStates[i] == 2
                  && this.rules
                     .isWaterlogMissing(this.targets[i], this.view.getBlockState(this.targets[i].pos()))) {
                  this.giveUpCell(i, "waterlog stuck: " + this.noWorkReason);
                  n++;
               }
            }

            this.lastProgressTick = this.env.currentTick();
            if (n > 0) {
               return new PrintCore.aK(1);
            }
         }

         return this.stallStep();
      }
   }

   LongArrayList init_LongArrayList_I(int cell) {
      LongArrayList blocks = new LongArrayList();
      if (this.cellStates[cell] == 0 && this.targets[cell].kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLUID) {
         BlockPos source = this.targets[cell].pos();
         this.init_V_LongArrayList_BlockPos(blocks, source);
         PrintCore.aB shape = this.spillShapeOf(cell);
         if (shape != null) {
            for (Direction direction : Direction.values()) {
               this.init_V_LongArrayList_BlockPos(blocks, source.relative(direction));
            }

            for (BlockPos outlet : shape.read) {
               this.init_V_LongArrayList_BlockPos(blocks, outlet);
               this.init_V_LongArrayList_BlockPos(blocks, outlet.below());
            }
         }

         return blocks;
      } else {
         return blocks;
      }
   }

   private void init_V_LongArrayList_BlockPos(LongArrayList blocks, BlockPos pos) {
      long key = pos.asLong();
      if (this.temporaryBlocks.containsKey(key)
         && !this.pendingTemporary.containsKey(key)
         && !this.ownerStillOpen(key)
         && !this.tick_Z_J(key)
         && !this.sync_Z_J(key)
         && !blocks.contains(key)) {
         blocks.add(key);
      }
   }

   PrintCore.PrintStep init_UiHelper_NetHelper_TokenStore_TaskQue_I(PrintNav.Inner_TaskQueue reach, int cell) {
      LongArrayList goals = this.init_LongArrayList_I(cell);
      if (goals.isEmpty()) {
         return null;
      }

      goals.sort(highestNearestFirst(this.env.playerMotionState()));

      for (long key : goals) {
         this.cleanupCandidates.add(key);
         BlockPos block = BlockPos.of(key);
         PrintCore.PrintStep dig = this.digStep(
            reach, block, "preparing fluid at " + this.targets[cell].pos().toShortString()
         );
         if (dig != null) {
            return dig;
         }

         if (this.run(block) && this.update_Z_BlockPos(block) && this.write_Z_BlockPos_BlockPos(block, block)) {
            return new PrintCore.StreamGate(block, true);
         }
      }

      PrintCore.r failure = this.failedApproaches.get(cell);
      return failure != null
            && failure.start() == reach.startKey
            && failure.feet() == reach.feetYOf(reach.startKey)
            && failure.goals().equals(goals)
            && failure.policy().init()
         ? this.waitOneTick
         : new PrintCore.ac(reach, cell, goals);
   }

   void predictFlow(BlockPos source, Fluid fluid) {
      this.strictFlowCheck = false;

      try {
         this.findSpill(source, fluid);
      } finally {
         this.strictFlowCheck = true;
      }
   }

   BlockPos findSpill(BlockPos source, Fluid fluid) {
      long t0 = System.nanoTime();

      try {
         return this.traceSpill(source, fluid);
      } finally {
         this.leakNanos = this.leakNanos + (System.nanoTime() - t0);
      }
   }

   private BlockPos traceSpill(BlockPos source, Fluid fluid) {
      this.predictedFlow.clear();
      this.predictedFlow.add(source.asLong());
      Long2IntOpenHashMap seen = new Long2IntOpenHashMap();
      seen.defaultReturnValue(-1);
      ArrayDeque<long[]> queue = new ArrayDeque<>();
      boolean water = fluid.isSame(Fluids.WATER);
      int reach = fluid.isSame(Fluids.LAVA) ? 3 : 7;
      queue.add(new long[]{source.asLong(), reach});
      seen.put(source.asLong(), reach);
      int budget = 6000;

      while (!queue.isEmpty() && budget-- > 0) {
         long[] e = queue.poll();
         BlockPos at = BlockPos.of(e[0]);
         int left = (int)e[1];
         int ti = this.cellIndexByPos.get(at.asLong());
         boolean sourceCell = at.equals(source)
            || this.view.getBlockState(at).getFluidState().isSource()
            || ti >= 0
               && this.targets[ti].kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLUID
               && this.targets[ti].wanted().getFluidState().getType().isSame(fluid);
         if (sourceCell) {
            left = reach;
         }

         BlockPos below = at.below();
         if (!this.env.hasChunkAt(below)) {
            return below;
         }

         boolean down = this.init_Z_BlockPos_Fluid(below, fluid);
         if (down) {
            BlockPos bad = this.read_BlockPos_BlockPos_Fluid(below, fluid);
            if (bad != null && this.strictFlowCheck) {
               return bad;
            }

            if (seen.get(below.asLong()) < reach) {
               seen.put(below.asLong(), reach);
               queue.add(new long[]{below.asLong(), reach});
               this.predictedFlow.add(below.asLong());
            }
         }

         if ((!down || sourceCell) && left > 0) {
            for (Direction d : Plane.HORIZONTAL) {
               BlockPos next = at.relative(d);
               if (!this.env.hasChunkAt(next)) {
                  return next;
               }

               if (this.strictFlowCheck && water && sourceCell) {
                  BlockPos footing = this.init_BlockPos_BlockPos_BlockPos(at, next);
                  if (footing != null) {
                     return footing;
                  }
               }

               PrintCore.aB shaped = ti < 0 ? null : this.spillShapeOf(ti);
               if ((shaped == null || !shaped.outside.contains(next) || !this.load_Z_UiHelper_aB(shaped)) && this.init_Z_BlockPos_Fluid(next, fluid)) {
                  BlockPos bad = this.read_BlockPos_BlockPos_Fluid(next, fluid);
                  if (bad != null && this.strictFlowCheck) {
                     return bad;
                  }

                  if (seen.get(next.asLong()) < left - 1) {
                     seen.put(next.asLong(), left - 1);
                     this.predictedFlow.add(next.asLong());
                     queue.add(new long[]{next.asLong(), left - 1});
                  }
               }
            }
         }
      }

      return queue.isEmpty() ? null : BlockPos.of(queue.peek()[0]);
   }

   private BlockPos init_BlockPos_BlockPos_BlockPos(BlockPos incoming, BlockPos dry) {
      BlockPos below = dry.below();
      long key = below.asLong();
      if (!this.temporaryBlocks.containsKey(key) && !this.view.isOwnedTemporaryAt(below)) {
         return null;
      }

      BlockState boundary = this.view.getBlockState(dry);
      BooleanProperty property = BlockStateProperties.WATERLOGGED;
      if (boundary.hasProperty(property) && !boundary.getValue(property) && this.view.getBlockState(below).isSolid()) {
         int sourceCell = this.cellIndexByPos.get(dry.asLong());
         if (sourceCell >= 0 && !this.targets[sourceCell].wanted().getFluidState().isEmpty()) {
            return null;
         }

         for (Direction side : Plane.HORIZONTAL) {
            BlockPos other = dry.relative(side);
            if (!other.equals(incoming)) {
               FluidState water = this.view.getFluidState(other);
               if (!this.env.hasChunkAt(other) || water.isSource() && water.is(FluidTags.WATER)) {
                  if (!this.view.hasHypotheses() && this.temporaryBlocks.containsKey(key)) {
                     this.cleanupCandidates.add(key);
                  }

                  return below;
               }
            }
         }

         return null;
      } else {
         return null;
      }
   }

   private boolean init_Z_BlockPos_Fluid(BlockPos p, Fluid fluid) {
      if (!this.temporaryBlocks.containsKey(p.asLong()) && !this.view.isOwnedTemporaryAt(p)) {
         BlockState s = this.view.getBlockState(p);
         if (s == PrintView.UNLOADED_SENTINEL) {
            return false;
         } else {
            FluidState held = s.getFluidState();
            if (!held.isEmpty()) {
               return held.getType().isSame(fluid);
            } else if (s.isAir()) {
               return true;
            } else {
               return s.getBlock() instanceof LiquidBlockContainer
                  ? false
                  : s.canBeReplaced(fluid) || !s.isSolid() && !s.isCollisionShapeFullBlock(this.view, p);
            }
         }
      } else {
         return true;
      }
   }

   private BlockPos read_BlockPos_BlockPos_Fluid(BlockPos p, Fluid fluid) {
      int i = this.cellIndexByPos.get(p.asLong());
      if (i >= 0) {
         PrintTarget t = this.targets[i];
         if (!t.wanted().getFluidState().isEmpty() && t.wanted().getFluidState().getType().isSame(fluid)) {
            return null;
         }

         if (t.kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLOW) {
            return null;
         }
      }

      return p;
   }

   private PrintCore.PrintStep pourStep(PrintNav.Inner_TaskQueue reach) {
      if (this.noPourRevision == this.view.worldMutationRevision()
         && this.noPourStart == reach.startKey
         && this.noPourFluid == this.only
         && this.noPourPolicy != null
         && this.noPourPolicy.init()) {
         return null;
      }

      PrintCore.ah plan = new PrintCore.ah(reach, this.only);
      return plan.init_IntArrayList.isEmpty() ? null : plan;
   }

   private PrintCore.PrintStep wetTemporaryStep(PrintNav.Inner_TaskQueue reach) {
      if (this.temporaryBlocks.isEmpty()) {
         return null;
      }

      ArrayList<Long> wet = new ArrayList<>();

      for (long key : this.temporaryBlocks.keySet()) {
         if (this.predictedFlow.contains(key) && !this.tick_Z_J(key)) {
            wet.add(key);
         }
      }

      if (wet.isEmpty()) {
         return null;
      }

      wet.sort(highestNearestFirst(this.env.playerMotionState()));

      for (long key : wet) {
         if (!this.ownerStillOpen(key)) {
            this.cleanupCandidates.add(key);
            BlockPos p = BlockPos.of(key);
            PrintCore.PrintStep dig = this.digStep(reach, p, "before pouring");
            if (dig != null) {
               return dig;
            }

            if (this.run(p) && this.update_Z_BlockPos(p) && this.write_Z_BlockPos_BlockPos(p, p)) {
               return new PrintCore.StreamGate(p, true);
            }
         }
      }

      BlockPos here = PrintNav.resolveStandingCell(this.view, this.feetPosition());

      for (long key : wet) {
         if (!this.ownerStillOpen(key)) {
            PrintCore.PrintStep climb = this.approachStep(here, BlockPos.of(key), "before pouring");
            if (climb != null) {
               return climb;
            }
         }
      }

      return this.waitOneTick;
   }

   private static boolean wantsWaterlogged(PrintTarget target) {
      BooleanProperty property = BlockStateProperties.WATERLOGGED;
      return target.wanted().hasProperty(property) && target.wanted().getValue(property);
   }

   private PrintCore.PrintStep waterlogStep(PrintNav.Inner_TaskQueue reach) {
      if (this.waterloggedCells == null) {
         IntArrayList cells = new IntArrayList();

         for (int i = 0; i < this.targets.length; i++) {
            if (wantsWaterlogged(this.targets[i])) {
               cells.add(i);
            }
         }

         this.waterloggedCells = cells.toIntArray();
      }

      autismclient.ai.print.PrintClicks.Inner_DataUtil budget = new autismclient.ai.print.PrintClicks.Inner_DataUtil(4000);

      for (int i : this.waterloggedCells) {
         PrintTarget target = this.targets[i];
         if (this.cellStates[i] == 2
            && !(target.pos().distToCenterSqr(this.feetPosition()) > square(5.5))
            && this.rules.isWaterlogMissing(target, this.view.getBlockState(target.pos()))
            && this.findSpill(target.pos(), target.wanted().getFluidState().getType()) == null) {
            for (long key : this.stancesNear(reach, target.pos(), true)) {
               if (!this.refusedCellStances.contains(cellStanceKey(i, key))) {
                  for (Vec3 point : PrintClicks.getCandidateFeetPositions(this.view, key, reach.feetYOf(key))) {
                     autismclient.ai.print.PrintClicks.Inner_StreamUtil click = PrintClicks.findClick(
                        this.view,
                        this.env,
                        this.rules,
                        target,
                        PrintClicks.getFluidBucketItem(target),
                        PrintClicks.Inner_CachePool.WATERLOG,
                        point,
                        false,
                        false,
                        budget,
                        4.1000000000000005
                     );
                     if (click != null
                        && this.hasWayOut(reach, key)
                        && this.init_Z_J_ListPool(key, target)
                        && this.init_Z_TokenStore_TaskQue_ListPool(reach, target)
                        && !this.takesLastWay(target.pos(), target.wanted())) {
                        this.predictFlow(target.pos(), target.wanted().getFluidState().getType());
                        PrintCore.PrintStep drain = this.wetTemporaryStep(reach);
                        if (drain != this.waitOneTick) {
                           if (drain != null) {
                              return drain;
                           }

                           PrintCore.PrintStep shaping = this.fallingFlowStep(reach);
                           if (shaping != this.waitOneTick) {
                              if (shaping != null) {
                                 return shaping;
                              }

                              this.logTrace("waterlog: completing nearby " + target.pos().toShortString());
                              PrintCore.PrintStep pour = new PrintCore.aj(i, PrintClicks.Inner_CachePool.WATERLOG, key, point);
                              return key == reach.startKey ? pour : new PrintCore.aL(reach.reconstructPath(key), reach, pour);
                           }
                        }
                        break;
                     }
                  }

                  if (budget.isExhausted()) {
                     return null;
                  }
               }
            }
         }
      }

      return null;
   }

   private boolean shouldHoldLava() {
      if (this.flags_Z) {
         return false;
      }

      for (int i : this.fluidCellsByHeight()) {
         if (this.cellStates[i] != 3 && this.cellStates[i] != 5) {
            PrintTarget t = this.targets[i];
            if (t.kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLUID && t.wanted().getFluidState().getType().isSame(Fluids.WATER)) {
               return true;
            }
         }
      }

      return false;
   }

   private int[] fluidOrWaterlogged() {
      if (this.fluidOrWaterloggedCells == null) {
         IntArrayList cells = new IntArrayList();

         for (int i = 0; i < this.targets.length; i++) {
            if (this.targets[i].kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLUID || wantsWaterlogged(this.targets[i])) {
               cells.add(i);
            }
         }

         this.fluidOrWaterloggedCells = cells.toIntArray();
      }

      return this.fluidOrWaterloggedCells;
   }

   private int[] fluidCellsByHeight() {
      if (this.fluidCellsTopDown == null) {
         this.fluidCellsTopDown = Arrays.stream(this.fluidWorkByHeight())
            .filter(i -> this.targets[i].kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLUID)
            .toArray();
      }

      return this.fluidCellsTopDown;
   }

   private int[] fluidWorkByHeight() {
      if (this.fluidWorkTopDown == null) {
         List<Integer> order = new ArrayList<>();

         for (int i : this.fluidOrWaterlogged()) {
            order.add(i);
         }

         order.sort((a, b) -> Integer.compare(this.targets[b].pos().getY(), this.targets[a].pos().getY()));
         this.fluidWorkTopDown = order.stream().mapToInt(Integer::intValue).toArray();
      }

      return this.fluidWorkTopDown;
   }

   private boolean init_Z_TokenStore_TaskQue_ListPool(PrintNav.Inner_TaskQueue reach, PrintTarget t) {
      if (this.findSpill(t.pos(), t.wanted().getFluidState().getType()) != null) {
         return false;
      }

      LongOpenHashSet flow = new LongOpenHashSet(this.predictedFlow);
      boolean touches = false;

      for (long k : flow) {
         if (reach.isReachable(k) || reach.isReachable(BlockPos.offset(k, Direction.DOWN))) {
            touches = true;
            break;
         }
      }

      if (!touches) {
         return true;
      }

      BlockState water = t.wanted().getFluidState().getType().defaultFluidState().createLegacyBlock();
      List<BlockPos> assumed = new ArrayList<>();

      for (long k : flow) {
         BlockPos p = BlockPos.of(k);
         if (this.view.getBlockState(p).isAir()) {
            this.view.pushHypothesis(p, water);
            assumed.add(p);
         } else if (p.equals(t.pos()) && t.kind() != autismclient.ai.print.PrintTarget.Inner_DataUtil.FLUID) {
            this.view.pushHypothesis(p, t.wanted());
            assumed.add(p);
         }
      }

      try {
         BlockPos src = t.pos();
         PrintNav.Inner_TaskQueue after = PrintNav.searchReachable(
            this.view, BlockPos.of(reach.startKey), this.bounds, 5000, this::isRideable
         );

         for (long k : reach.costByCell.keySet()) {
            if (Math.max(Math.abs(BlockPos.getX(k) - src.getX()), Math.max(Math.abs(BlockPos.getY(k) - src.getY()), Math.abs(BlockPos.getZ(k) - src.getZ())))
                  <= 10
               && !after.isReachable(k)) {
               long up = BlockPos.offset(k, Direction.UP);
               if (!flow.contains(k) && !flow.contains(up) && !after.truncatedByNodeLimit) {
                  return false;
               }
            }
         }

         return true;
      } finally {
         for (BlockPos p : assumed) {
            this.view.popHypothesis(p);
         }
      }
   }

   private boolean clear(BlockPos p) {
      for (int dy = 1; dy <= 4; dy++) {
         for (int dx = -3; dx <= 3; dx++) {
            for (int dz = -3; dz <= 3; dz++) {
               if (dx != 0 || dz != 0) {
                  int i = this.cellIndexByPos.get(BlockPos.asLong(p.getX() + dx, p.getY() + dy, p.getZ() + dz));
                  if (i >= 0
                     && this.targets[i].kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLUID
                     && this.cellStates[i] != 3
                     && this.cellStates[i] != 5
                     && this.findSpill(this.targets[i].pos(), this.targets[i].wanted().getFluidState().getType()) == null) {
                     return true;
                  }
               }
            }
         }
      }

      return false;
   }

   boolean pop_Z_I(int i) {
      if (i < 0) {
         return true;
      }

      PrintTarget t = this.targets[i];
      return (t.kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLUID || t.kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLOW)
         && this.cellStates[i] != 3
         && this.cellStates[i] != 1;
   }

   private boolean reset(BlockPos filled) {
      for (Direction direction : Direction.values()) {
         BlockPos inner = filled.relative(direction);
         if (this.confirmedAirCells.contains(inner.asLong()) && this.view.getBlockState(inner).isAir()) {
            boolean open = false;

            for (Direction side : Direction.values()) {
               BlockPos exit = inner.relative(side);
               if (!exit.equals(filled)) {
                  int source = this.cellIndexByPos.get(exit.asLong());
                  BlockState state = source < 0 ? this.view.getBlockState(exit) : this.targets[source].wanted();
                  if (state.isAir() || state != PrintView.UNLOADED_SENTINEL && state.canBeReplaced()) {
                     open = true;
                     break;
                  }
               }
            }

            if (!open) {
               return false;
            }
         }
      }

      return true;
   }

   private PrintCore.PrintStep refillExcavatedStep(PrintNav.Inner_TaskQueue reach) {
      return this.refillExcavatedStep(reach, false);
   }

   private PrintCore.PrintStep refillExcavatedStep(PrintNav.Inner_TaskQueue reach, boolean servedOnly) {
      Item temp = this.tempItem();
      if (!(temp instanceof BlockItem tempBlock)) {
         return null;
      } else {
         BlockState state = tempBlock.getBlock().defaultBlockState();
         List<Long> cells = new ArrayList<>(this.confirmedAirCells);
         cells.sort(Comparator.comparingInt(BlockPos::getY));
         autismclient.ai.print.PrintClicks.Inner_DataUtil budget = new autismclient.ai.print.PrintClicks.Inner_DataUtil(20000);

         for (long cellKey : cells) {
            BlockPos p = BlockPos.of(cellKey);
            if (this.env.hasChunkAt(p) && this.view.getBlockState(p) != PrintView.UNLOADED_SENTINEL) {
               if (!this.view.getBlockState(p).isAir()) {
                  this.confirmedAirCells.remove(cellKey);
               } else if ((!this.confirmedAirCells.contains(p.below().asLong()) || !this.view.getBlockState(p.below()).isAir())
                  && (!servedOnly || this.excavationOwner.containsKey(cellKey) && this.cellStates[this.excavationOwner.get(cellKey)] == 3)
                  && !this.abandonedCells.contains(cellKey)
                  && this.reset(p)) {
                  PrintTarget probe = new PrintTarget(-1, p, state, autismclient.ai.print.PrintTarget.Inner_DataUtil.PLACE, temp, null);

                  for (int dx = -4; dx <= 4; dx++) {
                     for (int dz = -4; dz <= 4; dz++) {
                        for (int dy = -3; dy <= 4; dy++) {
                           long key = BlockPos.asLong(p.getX() + dx, p.getY() + dy, p.getZ() + dz);
                           if (reach.isReachable(key)
                              && (key == reach.startKey || !this.failedWalkStances.contains(key))
                              && this.hasWayOut(reach, key)) {
                              for (Vec3 feet : PrintClicks.getCandidateFeetPositions(this.view, key, reach.feetYOf(key))) {
                                 if (PrintClicks.findClick(
                                       this.view,
                                       this.env,
                                       this.rules,
                                       probe,
                                       temp,
                                       PrintClicks.Inner_CachePool.PLACE,
                                       feet,
                                       true,
                                       false,
                                       budget,
                                       4.1000000000000005
                                    )
                                    != null) {
                                    this.logTrace("pit: filling " + p.toShortString());
                                    PrintCore.PrintStep place = new PrintCore.O(p, temp, key, feet);
                                    return key == reach.startKey ? place : new PrintCore.aL(reach.reconstructPath(key), reach, place);
                                 }
                              }
                           }
                        }
                     }
                  }
               }
            }
         }

         return null;
      }
   }

   private PrintCore.PrintStep decideTeardown() {
      if (this.openCells == 0
         && !this.machineJobs.isEmpty()
         && this.fluidWorkTopDown.length == 0
         && this.confirmedAirCells.isEmpty()
         && this.pendingTemporary.isEmpty()) {
         BlockPos helper = null;
         double distance = 1.0 / 0.0;

         for (BlockPos candidate : this.slopeHelpers().values()) {
            BlockState recorded = this.temporaryBlocks.get(candidate.asLong());
            if (recorded != null && recorded.getBlock() instanceof BaseRailBlock) {
               if (!this.env.hasChunkAt(candidate)) {
                  return new PrintCore.T(new autismclient.ai.print.PrintChunkWork.Inner_StreamUtil(PrintChunkWork.chunkKey(candidate)));
               }

               if (this.get(candidate)) {
                  double next = candidate.distToCenterSqr(this.feetPosition());
                  if (next < distance) {
                     helper = candidate;
                     distance = next;
                  }
               }
            }
         }

         if (helper == null) {
            this.verifyWithAccess = true;
            this.phase = PrintCore.J.VERIFY;
            this.reason = "Using existing construction access for saved machine work";
            return this.decideVerify();
         }

         PrintCore.PrintStep removal = this.approachStep(
            PrintNav.resolveStandingCell(this.view, this.feetPosition()), helper, "slope: removing the finished helper before machine activation"
         );
         if (removal != null) {
            return removal;
         }
      }

      if (this.teardownStartCount < 0 || this.teardownStartBlocks.isEmpty() && this.temporaryBlocks.size() < this.teardownStartCount) {
         this.teardownStartBlocks.clear();
         this.teardownStartBlocks.addAll(this.temporaryBlocks.keySet());
         this.teardownStartCount = this.temporaryBlocks.size();
      }

      if (this.retryGivenUpBeforeTeardown()) {
         return new PrintCore.aK(1);
      }

      this.view.requireDropOvershootSafety = false;
      if (!this.confirmedAirCells.isEmpty()) {
         autismclient.ai.engine.AiPhysics.MotionState b0 = this.env.playerMotionState();
         PrintCore.PrintStep fill = this.refillExcavatedStep(
            this.reachFrom(PrintNav.resolveStandingCell(this.view, new Vec3(b0.x(), b0.y(), b0.z())))
         );
         if (fill != null) {
            return fill;
         }
      }

      if (this.temporaryBlocks.isEmpty() && this.pendingTemporary.isEmpty()) {
         if (!this.confirmedAirCells.isEmpty() && this.pitFillAttempts < 6) {
            this.pitFillAttempts++;

            for (long k : this.confirmedAirCells) {
               this.abandonedCells.remove(k);
            }

            autismclient.ai.engine.AiPhysics.MotionState b2 = this.env.playerMotionState();
            BlockPos h2 = PrintNav.resolveStandingCell(this.view, new Vec3(b2.x(), b2.y(), b2.z()));
            PrintCore.PrintStep fill = this.refillExcavatedStep(this.reachFrom(h2));
            if (fill != null) {
               return fill;
            }

            Item temp = this.tempItem();
            BlockState tempState = temp instanceof BlockItem bi ? bi.getBlock().defaultBlockState() : null;
            LongArrayList cells = new LongArrayList();
            long lowestPit = -9223372036854775808L;

            for (long k : this.confirmedAirCells) {
               if (lowestPit == -9223372036854775808L || BlockPos.getY(k) < BlockPos.getY(lowestPit)) {
                  lowestPit = k;
               }
            }

            cells.add(lowestPit);
            double feetY = this.view.standingHeightAt(h2.getX(), h2.getY(), h2.getZ());
            if (Double.isNaN(feetY)) {
               feetY = b2.y();
            }

            PrintAccess access = new PrintAccess(this, 80.0);
            PrintAccess.Inner_BufferHelper plan = tempState == null ? null : access.planToCells(h2, feetY, cells, tempState, temp, 20000);
            if (plan != null && !plan.steps().isEmpty()) {
               this.logTrace("pit: access plan " + plan.steps().size() + " steps to fill " + BlockPos.of(lowestPit).toShortString());
               return new PrintCore.AccessPlanStep(plan, temp);
            }

            this.logTrace("pit: nothing fills " + BlockPos.of(lowestPit).toShortString() + (plan == null ? " (" + access.failureDetail + ")" : ""));
         }

         this.phase = PrintCore.J.VERIFY;
         this.reason = "Checking";
         return this.decideVerify();
      } else {
         autismclient.ai.engine.AiPhysics.MotionState b1 = this.env.playerMotionState();
         PrintCore.PrintStep slopeUndo = this.read_UiHelper_NetHelper_BlockPos(PrintNav.resolveStandingCell(this.view, new Vec3(b1.x(), b1.y(), b1.z())));
         if (slopeUndo != null) {
            return slopeUndo;
         }

         PrintCore.PrintStep undo = this.init_UiHelper_NetHelper_BlockPos_Z(PrintNav.resolveStandingCell(this.view, new Vec3(b1.x(), b1.y(), b1.z())), true);
         if (undo != null) {
            return undo;
         }

         this.reason = "Removing temporary blocks (" + this.temporaryBlocks.size() + " left)";
         b1 = this.env.playerMotionState();
         BlockPos here = PrintNav.resolveStandingCell(this.view, new Vec3(b1.x(), b1.y(), b1.z()));
         long under = BlockPos.asLong(here.getX(), here.getY() - 1, here.getZ());
         this.logTrace(
            "teardown: " + this.temporaryBlocks.size() + " temps, body " + formatVec(this.feetPosition()) + " stance " + here.toShortString()
         );
         if (this.trackLocalTemporaries) {
            this.localTemporaries.addAll(this.pendingTemporary.keySet());
            this.trackLocalTemporaries = false;
         }

         this.localTemporaries.removeIf(kx -> !this.temporaryBlocks.containsKey(kx) && !this.pendingTemporary.containsKey(kx));
         if (!this.upperPassTried && this.isAboveBase(here)) {
            this.upperPassTried = true;
            PrintCore.PrintStep upper = this.upperPassStep(here, b1);
            if (upper != null) {
               return upper;
            }
         }

         List<Long> sideWork = this.sideWork(here, b1.position());
         sideWork.sort(highestNearestFirst(b1));
         if (!sideWork.isEmpty()) {
            PrintCore.PrintStep sideRemoval = this.removalStep(
               this.reachFrom(here), sideWork, new autismclient.ai.print.PrintClicks.Inner_DataUtil(40000), b1.y() - 0.6
            );
            if (sideRemoval != null) {
               return sideRemoval;
            }
         }

         if (this.isAboveBase(here)) {
            List<Long> high = new ArrayList<>();
            long highSig = 17L;

            for (int pass = 0; pass < 2 && high.isEmpty(); pass++) {
               for (long k : this.temporaryBlocks.keySet()) {
                  if (BlockPos.getY(k) >= b1.y() - 0.001
                     && this.localTemporaries.contains(k) == (pass == 1)
                     && (BlockPos.getX(k) != here.getX() || BlockPos.getZ(k) != here.getZ())) {
                     high.add(k);
                     highSig = highSig * 31L + k;
                  }
               }
            }

            if (!high.isEmpty()) {
               high.sort(highestNearestFirst(b1));
               PrintCore.PrintStep a = this.removalStep(
                  this.reachFrom(here), high, new autismclient.ai.print.PrintClicks.Inner_DataUtil(40000)
               );
               if (a != null) {
                  return a;
               }

               if (this.highClimbTried.getOrDefault(here.asLong(), -9223372036854775808L) != highSig) {
                  this.highClimbTried.put(here.asLong(), highSig);
                  int top = -2147483648;

                  for (long k : high) {
                     top = Math.max(top, BlockPos.getY(k));
                  }

                  LongArrayList goals = new LongArrayList();

                  for (long k : high) {
                     if (BlockPos.getY(k) == top) {
                        goals.add(k);
                     }
                  }

                  if (!this.climbFailedBefore(here, goals)) {
                     return this.teardownClimb(here, b1, goals, true);
                  }
               }
            }
         }

         if (!this.localTemporaries.isEmpty()) {
            ArrayList<Long> localWork = new ArrayList<>();

            for (long key : this.temporaryBlocks.keySet()) {
               if (BlockPos.getY(key) >= here.getY() - 5 && (BlockPos.getX(key) != here.getX() || BlockPos.getZ(key) != here.getZ())) {
                  localWork.add(key);
               }
            }

            localWork.sort(highestNearestFirst(b1));
            PrintCore.PrintStep localRemoval = this.removalStep(
               this.reachFrom(here), localWork, new autismclient.ai.print.PrintClicks.Inner_DataUtil(40000), b1.y() - 0.6
            );
            if (localRemoval != null) {
               return localRemoval;
            }

            List<Long> others = new ArrayList<>();

            for (long k : this.temporaryBlocks.keySet()) {
               if (!this.localTemporaries.contains(k)) {
                  others.add(k);
               }
            }

            others.sort(highestNearestFirst(b1));
            PrintCore.PrintStep a = this.removalStep(
               this.reachFrom(here), others, new autismclient.ai.print.PrintClicks.Inner_DataUtil(40000)
            );
            if (a != null) {
               return a;
            }

            LongArrayList higher = new LongArrayList();

            for (long key : others) {
               if (BlockPos.getY(key) >= here.getY() - 5) {
                  higher.add(key);
               }
            }

            if (!higher.isEmpty()
               && this.higherClimbTried.getOrDefault(here.asLong(), -9223372036854775808L) != this.view.worldMutationRevision()
               && !this.climbFailedBefore(here, higher)) {
               this.higherClimbTried.put(here.asLong(), this.view.worldMutationRevision());
               return this.teardownClimb(here, b1, higher, true);
            }

            if (others.isEmpty()) {
               this.localTemporaries.clear();
            }
         }

         if (this.temporaryBlocks.containsKey(under) && !this.sync_Z_J(under) && this.update_Z_BlockPos(BlockPos.of(under))) {
            PrintCore.PrintStep removal = this.removalAt(
               this.reachFrom(here), here.asLong(), BlockPos.of(under), true, null
            );
            if (removal != null) {
               return removal;
            }
         }

         PrintNav.Inner_TaskQueue reach = this.reachFrom(here);
         List<Long> order = new ArrayList<>(this.temporaryBlocks.keySet());
         order.sort(Comparator.comparingInt(kx -> -BlockPos.getY(kx)));
         PrintCore.PrintStep pick = this.removalStep(
            reach, order, new autismclient.ai.print.PrintClicks.Inner_DataUtil(40000)
         );
         if (pick != null) {
            return pick;
         }

         int maxY = -2147483648;

         for (long k : this.temporaryBlocks.keySet()) {
            maxY = Math.max(maxY, BlockPos.getY(k));
         }

         if (maxY > b1.y() + 4.0 && this.topClimbTried.add(here.asLong())) {
            LongArrayList top = new LongArrayList();

            for (long k : this.temporaryBlocks.keySet()) {
               if (BlockPos.getY(k) == maxY) {
                  top.add(k);
               }
            }

            if (top.size() < this.temporaryBlocks.size() && !this.climbFailedBefore(here, top)) {
               return this.teardownClimb(here, b1, top, true);
            }
         }

         if (this.allClimbTried.add(here.asLong())) {
            LongArrayList goals = new LongArrayList(this.temporaryBlocks.keySet());
            if (!this.climbFailedBefore(here, goals)) {
               return this.teardownClimb(here, b1, goals, false);
            }
         }

         this.noWorkReason = this.temporaryBlocks.size() + " temporary blocks out of reach";
         if (++this.teardownStallRounds % 10 == 0) {
            this.failedDigStances.clear();
            this.failedClicks.clear();
            this.allClimbTried.clear();
            this.topClimbTried.clear();
            this.failedWalkStances.clear();
            this.failedClimbs.clear();
            this.progressRevision++;
         }

         return this.stallStep();
      }
   }

   private static long climbSignature(BlockPos from, LongArrayList goals) {
      long sum = 0L;
      long mix = 0L;

      for (int i = 0; i < goals.size(); i++) {
         long g = goals.getLong(i) * -7046029254386353131L;
         sum += g;
         mix ^= Long.rotateLeft(g, 31);
      }

      long column = BlockPos.asLong(from.getX(), 0, from.getZ());
      return (sum * 31L + mix) * 1099511628211L + column * 17L + goals.size();
   }

   private boolean climbFailedBefore(BlockPos here, LongArrayList goals) {
      return this.failedClimbs.contains(climbSignature(here, goals));
   }

   private List<Long> sideWork(BlockPos here, Vec3 body) {
      ArrayList<Long> candidates = new ArrayList<>();
      if (this.localTemporaries.isEmpty()) {
         return candidates;
      }

      for (long key : this.temporaryBlocks.keySet()) {
         if (this.localTemporaries.contains(key)
            && BlockPos.getY(key) >= body.y - 0.6
            && (BlockPos.getX(key) != here.getX() || BlockPos.getZ(key) != here.getZ())) {
            candidates.add(key);
         }
      }

      if (candidates.isEmpty()) {
         return candidates;
      }

      LongOpenHashSet unchecked = new LongOpenHashSet(candidates);
      Vec3[] eyes = new Vec3[]{PrintGeometry.init(body, false), PrintGeometry.init(body, true)};

      for (long original : this.temporaryBlocks.keySet()) {
         if (!this.localTemporaries.contains(original) && !this.sync_Z_J(original)) {
            Vec3 target = Vec3.atCenterOf(BlockPos.of(original));

            for (Vec3 eye : eyes) {
               if (!(eye.distanceToSqr(target) > 16.810000000000006)) {
                  BlockHitResult hit = this.view.raycastBlock(eye, target);
                  if (hit != null) {
                     unchecked.remove(hit.getBlockPos().asLong());
                  }
               }
            }

            if (unchecked.isEmpty()) {
               break;
            }
         }
      }

      candidates.removeIf(key -> unchecked.contains(key));
      return candidates;
   }

   private long ticksSinceTeardownWork(long now) {
      long work = this.temporaryBlocksRemoved + this.climbSteps;
      if (work != this.work) {
         this.work = work;
         this.lastTeardownWorkTick = now;
      }

      return now - this.lastTeardownWorkTick;
   }

   private PrintCore.PrintStep teardownClimb(
      BlockPos here, autismclient.ai.engine.AiPhysics.MotionState body, LongArrayList goals, boolean extending
   ) {
      return this.teardownClimb(here, body, goals, extending, false);
   }

   private boolean upperPassExhausted() {
      return this.upperPassAttempts >= 64 || this.upperPassReads >= 18000000L;
   }

   private PrintCore.PrintStep upperPassStep(BlockPos here, autismclient.ai.engine.AiPhysics.MotionState body) {
      if (this.upperPassExhausted()) {
         return null;
      }

      int top = (int)Math.ceil(body.y() + 32.0);
      LongArrayList highest = new LongArrayList();

      for (long key : this.temporaryBlocks.keySet()) {
         int y = BlockPos.getY(key);
         if (y >= top && !this.localTemporaries.contains(key) && !this.sync_Z_J(key)) {
            if (y > top) {
               highest.clear();
               top = y;
            }

            if (highest.size() < 512) {
               highest.add(key);
            }
         }
      }

      return highest.isEmpty() ? null : this.teardownClimb(here, body, highest, true, true);
   }

   private PrintCore.PrintStep teardownClimb(
      BlockPos here, autismclient.ai.engine.AiPhysics.MotionState body, LongArrayList goals, boolean extending, boolean upperFirst
   ) {
      Item temp = this.useGlassTemporaries ? Items.GLASS : this.tempItem();
      BlockState tempState = temp instanceof BlockItem bi ? bi.getBlock().defaultBlockState() : null;
      double feetY = this.view.standingHeightAt(here.getX(), here.getY(), here.getZ());
      if (Double.isNaN(feetY)) {
         feetY = body.y();
      }

      long under = here.below().asLong();
      long avoidSwap = this.view.getCollisionShape(here.below(2)).isEmpty() ? under : -9223372036854775808L;
      return new PrintCore.U(here, feetY, goals, tempState, temp, avoidSwap, extending, upperFirst);
   }

   private static Comparator<Long> highestNearestFirst(autismclient.ai.engine.AiPhysics.MotionState body) {
      return Comparator.<Long>comparingInt(k -> -BlockPos.getY(k))
         .thenComparingDouble(k -> -(square(BlockPos.getX(k) + 0.5 - body.x()) + square(BlockPos.getZ(k) + 0.5 - body.z())));
   }

   private static double square(double v) {
      return v * v;
   }

   private PrintCore.PrintStep removalStep(
      PrintNav.Inner_TaskQueue reach, List<Long> order, autismclient.ai.print.PrintClicks.Inner_DataUtil budget
   ) {
      return this.removalStep(reach, order, budget, -1.0 / 0.0);
   }

   private PrintCore.PrintStep removalStep(
      PrintNav.Inner_TaskQueue reach, List<Long> order, autismclient.ai.print.PrintClicks.Inner_DataUtil budget, double minimumFeet
   ) {
      if (this.phase == PrintCore.J.TEARDOWN) {
         if (order.isEmpty()) {
            return null;
         }

         this.resetRemovalMemo(reach);
         PrintCore.OrderedStances key = new PrintCore.OrderedStances(List.copyOf(order), minimumFeet);
         return this.triedRemovalOrders.contains(key) ? null : new PrintCore.V(reach, key);
      } else {
         for (long key : order) {
            if (!this.sync_Z_J(key)) {
               BlockPos p = BlockPos.of(key);
               PrintTarget probe = new PrintTarget(-1, p, this.view.getBlockState(p), autismclient.ai.print.PrintTarget.Inner_DataUtil.PLACE, Items.AIR, null);
               long top = BlockPos.asLong(p.getX(), p.getY() + 1, p.getZ());
               if (minimumFeet == -1.0 / 0.0
                  && reach.isReachable(top)
                  && reach.reconstructPath(top).size() <= 2
                  && (top == reach.startKey || !this.failedWalkStances.contains(top))
                  && this.update_Z_BlockPos(p)) {
                  PrintCore.PrintStep removal = this.removalAt(reach, top, p, true, null);
                  if (removal != null) {
                     return removal;
                  }
               }

               LongArrayList candidates = new LongArrayList();

               for (int dx = -4; dx <= 4; dx++) {
                  for (int dz = -4; dz <= 4; dz++) {
                     for (int dy = -4; dy <= 5; dy++) {
                        long sk = BlockPos.asLong(p.getX() + dx, p.getY() + dy, p.getZ() + dz);
                        if (reach.isReachable(sk) && reach.feetYOf(sk) >= minimumFeet) {
                           candidates.add(sk);
                        }
                     }
                  }
               }

               candidates.sort((a, b) -> Double.compare(reach.costOf(a), reach.costOf(b)));

               for (long sk : candidates) {
                  if (reach.isReachable(sk) && (sk == reach.startKey || !this.failedWalkStances.contains(sk))) {
                     if (sk == BlockPos.asLong(p.getX(), p.getY() + 1, p.getZ())) {
                        if (minimumFeet == -1.0 / 0.0 && this.update_Z_BlockPos(p)) {
                           PrintCore.PrintStep removal = this.removalAt(reach, sk, p, true, null);
                           if (removal != null) {
                              return removal;
                           }
                        }
                     } else if (!this.failedDigStances.contains(cellStanceKey((int)(p.asLong() & 2147483647L), sk))) {
                        autismclient.ai.print.PrintClicks.Inner_StreamUtil click = this.findClickAt(reach, sk, probe, budget);
                        PrintCore.PrintStep removal = this.removalFromStation(reach, sk, probe, click);
                        if (removal != null) {
                           return removal;
                        }
                     }
                  }
               }
            }
         }

         return null;
      }
   }

   private PrintCore.PrintStep removalFromStation(
      PrintNav.Inner_TaskQueue reach, long station, PrintTarget target, autismclient.ai.print.PrintClicks.Inner_StreamUtil click
   ) {
      return click == null ? null : this.removalAt(reach, station, target.pos(), false, click);
   }

   private void resetRemovalMemo(PrintNav.Inner_TaskQueue reach) {
      if (this.removalMemoRevision != this.view.worldMutationRevision() || this.removalMemoStart != reach.startKey) {
         this.triedRemovalStations.clear();
         this.removalStationTries = 0;
         this.triedRemovalOrders.clear();
         this.removalMemoRevision = this.view.worldMutationRevision();
         this.removalMemoStart = reach.startKey;
      }
   }

   private PrintCore.PrintStep removalAt(
      PrintNav.Inner_TaskQueue reach, long station, BlockPos position, boolean under, autismclient.ai.print.PrintClicks.Inner_StreamUtil click
   ) {
      if (this.phase != PrintCore.J.TEARDOWN) {
         if (this.hasWayOut(reach, station) && this.write_Z_BlockPos_BlockPos(under ? position : BlockPos.of(station), position)) {
            PrintCore.PrintStep dig = under
               ? new PrintCore.StreamGate(position, true)
               : new PrintCore.StreamGate(position, false, station, click.crouch(), click.feet());
            return station == reach.startKey ? dig : new PrintCore.aL(reach.reconstructPath(station), reach, dig);
         } else {
            return null;
         }
      } else {
         this.resetRemovalMemo(reach);
         LongOpenHashSet stations = this.triedRemovalStations.get(position.asLong());
         return stations != null && stations.contains(station) ? null : new PrintCore.W(reach, station, position, under, click);
      }
   }

