   private Set<Long> init_Set_Vec3(Vec3 body) {
      LinkedHashSet<Long> goals = new LinkedHashSet<>();
      int x = (int)Math.floor(body.x);
      int y = (int)Math.floor(body.y);
      int z = (int)Math.floor(body.z);

      for (BlockPos p : List.of(
         new BlockPos(this.bounds.minX() - 1, y, z),
         new BlockPos(this.bounds.maxX() + 1, y, z),
         new BlockPos(x, y, this.bounds.minZ() - 1),
         new BlockPos(x, y, this.bounds.maxZ() + 1),
         new BlockPos(x, this.maxTargetY() + 2, z)
      )) {
         if (PrintFlight.isFlightPointSafe(this.view, PrintFlight.cellFlightPoint(p.asLong()))) {
            goals.add(p.asLong());
         }
      }

      return goals;
   }

   private PrintCore.PrintStep decideCreative() {
      PrintCore.PrintStep early = this.earlyFillStep();
      if (early != null) {
         return early;
      }

      if (this.creativePlanMilestone != this.milestone) {
         this.creativePlanMilestone = this.milestone;
         this.creativePlanTick = this.env.currentTick();
         this.landingFailures.clear();
         this.task_LongOpenHashSet.clear();
         this.cellCooldowns.init();
         this.open_IntOpenHashSet.clear();
      }

      long searchOrigin = BlockPos.containing(this.feetPosition()).asLong();
      if (this.creativeSearchRevision != this.view.liveChangeRevision() || this.searchOrigin != searchOrigin) {
         this.creativeSearchRevision = this.view.liveChangeRevision();
         this.searchOrigin = searchOrigin;
         this.pool_LongOpenHashSet.clear();
         this.open_IntOpenHashSet.clear();
      }

      if (this.phase == PrintCore.J.TEARDOWN && this.temporaryBlocks.isEmpty() && this.pendingTemporary.isEmpty()) {
         this.phase = PrintCore.J.VERIFY;
         return this.decideVerify();
      } else {
         this.reachable = new PrintNav.Inner_TaskQueue(BlockPos.containing(this.feetPosition()).asLong());
         this.reachable.costByCell.put(this.reachable.startKey, 0.0);
         this.reachable.feetYByCell.put(this.reachable.startKey, this.env.playerMotionState().y());
         return new PrintCore.av();
      }
   }

   private boolean buffer(int i) {
      return this.cellStates[i] == 0
         && this.targets[i].kind() != autismclient.ai.print.PrintTarget.Inner_DataUtil.PARTNER
         && this.targets[i].kind() != autismclient.ai.print.PrintTarget.Inner_DataUtil.FLOW
         && (!this.cellCooldowns.isCoolingDown(i) || !this.open_IntOpenHashSet.contains(i) && this.node(i))
         && !this.set(i)
         && !this.heldBackCells.contains(i)
         && this.read_Z_I(i)
         && (
            this.targets[i].kind() != autismclient.ai.print.PrintTarget.Inner_DataUtil.FLUID
               || (this.spillShapeOf(i) == null || this.load_Z_UiHelper_aB(this.spillShapeOf(i)))
                  && this.findSpill(this.targets[i].pos(), this.targets[i].wanted().getFluidState().getType()) == null
         );
   }

   private PrintCore.PrintStep init_UiHelper_NetHelper_IntArrayList_Vec3(IntArrayList frontier, Vec3 origin) {
      ArrayList<Integer> candidates = new ArrayList<>();

      for (int i : frontier) {
         candidates.add(i);
      }

      for (int i = this.placedCells.nextSetBit(0); i >= 0; i = this.placedCells.nextSetBit(i + 1)) {
         if (!this.cellCooldowns.isCoolingDown(i) && !this.set(i) && !this.heldBackCells.contains(i) && this.read_Z_I(i)) {
            candidates.add(i);
         }
      }

      IntArrayList prioritized = new IntArrayList(Math.min(64, this.threatenedCells.size()));
      IntListIterator priorities = this.threatenedCells.iterator();

      while (priorities.hasNext() && prioritized.size() < 64) {
         int i = priorities.nextInt();
         prioritized.add(i);
         if ((this.cellStates[i] == 0 || this.cellStates[i] == 2)
            && !this.cellCooldowns.isCoolingDown(i)
            && !this.heldBackCells.contains(i)
            && this.read_Z_I(i)
            && !candidates.contains(i)) {
            candidates.add(i);
         }
      }

      for (int i : prioritized) {
         if (this.threatenedCells.remove(i)) {
            this.threatenedCells.add(i);
         }
      }

      if (this.nextOwner >= 0
         && (this.cellStates[this.nextOwner] == 0 || this.cellStates[this.nextOwner] == 2)
         && !this.heldBackCells.contains(this.nextOwner)
         && this.read_Z_I(this.nextOwner)
         && !candidates.contains(this.nextOwner)) {
         candidates.add(this.nextOwner);
      }

      boolean pending = !this.dispatchedCells.isEmpty();
      boolean unfinished = this.openCells > 0;
      candidates.sort(
         Comparator.<Integer>comparingInt(i -> this.stop(i) ? 0 : 1)
            .thenComparingInt(i -> i == this.nextOwner ? 0 : (this.threatenedCells.contains(i) ? 1 : 2))
            .thenComparingDouble(i -> this.targets[i].pos().distToCenterSqr(origin))
            .thenComparingInt(i -> this.targets[i].pos().getY())
            .thenComparingInt(i -> i)
      );
      if (!this.recoveries.isEmpty()) {
         int owner = this.recoveries.firstEntry().getValue().owner();
         candidates.removeIf(i -> i != owner);
      }

      this.update_List = List.copyOf(candidates);
      return new PrintCore.Y(candidates, pending, unfinished);
   }

   private PrintCore.PrintStep init_UiHelper_NetHelper_UiHelper_NetHelper(PrintCore.PrintStep next) {
      if (next instanceof PrintCore.ValueSink work && work.cell >= 0 && work.goal.click.mode() == PrintClicks.Inner_CachePool.PLACE) {
         return new PrintCore.CellGoalStep(work.cell, work.goal, next);
      } else {
         return next instanceof PrintCore.FlightLandingStep landing
               && landing.cell >= 0
               && landing.workGoal != null
               && landing.workGoal.click.mode() == PrintClicks.Inner_CachePool.PLACE
            ? new PrintCore.CellGoalStep(landing.cell, landing.workGoal, next)
            : next;
      }
   }

   private int read_I_Item(Item item) {
      for (int slot = 0; slot < 9; slot++) {
         if (matchesItem(this.env.getInventoryItem(slot), item)) {
            return 0;
         }
      }

      if (this.env.isCreativeMode()) {
         for (int slot = 0; slot < 9; slot++) {
            if (this.env.getInventoryItem(slot).isEmpty()) {
               return 1;
            }
         }

         return 2;
      } else {
         return 3;
      }
   }

