   private PrintCore.l previewActions(
      Vec3 pose, autismclient.ai.print.PrintClicks.Inner_StreamUtil first, IntArrayList pool, autismclient.ai.print.PrintClicks.Inner_DataUtil budget, int maxActions
   ) {
      ArrayList<Integer> cells = new ArrayList<>();
      LongArrayList assumed = new LongArrayList();
      HashMap<Item, Integer> used = new HashMap<>();
      autismclient.ai.print.PrintClicks.Inner_StreamUtil click = first;
      int ticks = 0;
      float yaw = first.yaw();
      float pitch = first.pitch();

      try {
         for (int step = 0; step < maxActions && click != null && !budget.isExhausted(); step++) {
            int i = click.target().index();
            if (this.view.hasHypothesisAt(click.target().pos())) {
               break;
            }

            int amount = used.getOrDefault(click.item(), 0);
            if (!this.env.isCreativeMode() && amount >= this.inventoryCount(click.item())) {
               break;
            }

            if (step > 0) {
               ticks += Math.max(0, (int)Math.ceil(Math.max(Math.abs(PrintGeometry.yawDelta(yaw, click.yaw())) / 60.0F, Math.abs(pitch - click.pitch()) / 45.0F)) - 1);
               if (this.targets[cells.get(cells.size() - 1)].item() != click.item()) {
                  ticks += this.read_I_Item(click.item());
               }

               if (hasSixWayLookFacing(click.target().wanted())
                  && autismclient.ai.engine.AiPlacementContext.init(yaw, pitch)[0] != autismclient.ai.engine.AiPlacementContext.init(click.yaw(), click.pitch())[0]) {
                  ticks += 5;
               }
            }

            ticks++;
            cells.add(i);
            used.put(click.item(), amount + 1);
            yaw = click.yaw();
            pitch = click.pitch();
            this.view.pushHypothesis(click.target().pos(), click.predicted());
            assumed.add(click.target().pos().asLong());
            Vec3 eye = PrintGeometry.init(pose, false);
            BlockHitResult ray = this.view.raycastBlock(eye, eye.add(PrintGeometry.lookDirection(yaw, pitch).scale(4.4)));
            int aligned = ray == null ? -1 : this.cellIndexByPos.get(ray.getBlockPos().relative(ray.getDirection()).asLong());
            autismclient.ai.print.PrintClicks.Inner_StreamUtil next = null;
            if (aligned >= 0
               && pool.contains(aligned)
               && !this.view.hasHypothesisAt(this.targets[aligned].pos())
               && this.buffer(aligned)
               && this.stop(aligned)
               && this.value(aligned)) {
               next = PrintClicks.tryClickWithLook(
                  this.view,
                  this.env,
                  this.rules,
                  this.targets[aligned],
                  this.targets[aligned].item(),
                  pose,
                  yaw,
                  pitch,
                  true,
                  false,
                  budget,
                  4.4,
                  this.constraintFor(aligned)
               );
            }

            if (next == null || next.item() != click.item() && this.read_I_Item(next.item()) > 0) {
               Item held = click.item();
               IntArrayList choices = new IntArrayList();
               double[] costs = new double[8];
               Arrays.fill(costs, 1.0 / 0.0);

               for (int candidate : pool) {
                  if (!this.view.hasHypothesisAt(this.targets[candidate].pos())
                     && this.buffer(candidate)
                     && this.stop(candidate)
                     && this.value(candidate)) {
                     Vec3 point = PrintView.blockCenter(this.targets[candidate].pos());
                     double cost = Math.abs(PrintGeometry.yawDelta(yaw, PrintGeometry.init(eye, point)))
                        + Math.abs(pitch - PrintGeometry.load(eye, point))
                        + (this.targets[candidate].item() == held ? 0 : this.read_I_Item(this.targets[candidate].item()) * 60);
                     int rank = 0;

                     while (rank < choices.size() && cost >= costs[rank]) {
                        rank++;
                     }

                     if (rank < 8) {
                        choices.add(rank, candidate);
                        if (choices.size() > 8) {
                           choices.removeInt(8);
                        }

                        for (int moved = Math.min(7, choices.size() - 1); moved > rank; moved--) {
                           costs[moved] = costs[moved - 1];
                        }

                        costs[rank] = cost;
                     }
                  }
               }

               double best = next == null ? 1.0 / 0.0 : this.read_I_Item(next.item());

               for (int tested = 0; tested < Math.min(8, choices.size()) && !budget.isExhausted(); tested++) {
                  int candidate = choices.get(tested);
                  PrintTarget target = this.targets[candidate];
                  autismclient.ai.print.PrintClicks.Inner_StreamUtil option = PrintClicks.findClick(
                     this.view,
                     this.env,
                     this.rules,
                     target,
                     target.item(),
                     PrintClicks.Inner_CachePool.PLACE,
                     pose,
                     true,
                     false,
                     budget,
                     4.4,
                     this.constraintFor(candidate),
                     null
                  );
                  if (option != null) {
                     double turn = Math.max(Math.abs(PrintGeometry.yawDelta(yaw, option.yaw())) / 60.0F, Math.abs(pitch - option.pitch()) / 45.0F);
                     double cost = Math.max(0.0, Math.ceil(turn) - 1.0) + (option.item() == held ? 0 : this.read_I_Item(option.item())) + turn * 0.01;
                     if (cost < best) {
                        next = option;
                        best = cost;
                     }
                  }
               }
            }

            click = next;
         }

         return new PrintCore.l(List.copyOf(cells), Math.max(1, ticks));
      } finally {
         for (int i = assumed.size() - 1; i >= 0; i--) {
            this.view.popHypothesis(BlockPos.of(assumed.getLong(i)));
         }
      }
   }

