   private boolean init_Z_Vec3_ListPool(Vec3 point, PrintTarget source) {
      AABB body = PrintGeometry.init(point.x, point.y, point.z, false).deflate(1.0E-6);
      if (this.view.intersectsHazard(body)) {
         return false;
      }

      if (body.minY >= source.pos().getY() + 1) {
         for (BlockPos pos : BlockPos.betweenClosed(BlockPos.containing(body.minX, body.minY, body.minZ), BlockPos.containing(body.maxX, body.maxY, body.maxZ))) {
            if (!this.view.getFluidState(pos).isEmpty()) {
               return false;
            }
         }

         return true;
      } else {
         for (BlockPos pos : BlockPos.betweenClosed(BlockPos.containing(body.minX, body.minY, body.minZ), BlockPos.containing(body.maxX, body.maxY, body.maxZ))) {
            int i = this.cellIndexByPos.get(pos.asLong());
            if (i >= 0
               && (
                  this.targets[i].kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLOW
                     || !this.targets[i].wanted().getFluidState().isEmpty()
               )) {
               return false;
            }
         }

         return true;
      }
   }

