   private List<BlockPos> load_List_I(int owner) {
      record Inner_DataUtil(BlockPos position, int users) {
      }

      ArrayList<Inner_DataUtil> candidates = new ArrayList<>(6);

      for (Direction side : Direction.values()) {
         BlockPos position = this.targets[owner].pos().relative(side);
         int users = 0;

         for (Direction face : Direction.values()) {
            int neighbor = this.cellIndexByPos.get(position.relative(face).asLong());
            if (neighbor >= 0
               && this.cellStates[neighbor] == 0
               && this.targets[neighbor].kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.PLACE
               && this.targets[neighbor].item() instanceof BlockItem
               && this.read_Z_I(neighbor)) {
               autismclient.ai.engine.PlacementGoal.PlaceConstraint placement = this.constraintFor(neighbor);
               if (placement == null || placement.acceptsFace(face)) {
                  users++;
               }
            }
         }

         candidates.add(new Inner_DataUtil(position, users));
      }

      candidates.sort(Comparator.comparingInt(Inner_DataUtil::users).reversed());
      return candidates.stream().map(Inner_DataUtil::position).toList();
   }

   private boolean node(int owner) {
      PrintTarget target = this.targets[owner];
      return !(target.wanted().getBlock() instanceof HopperBlock)
         ? false
         : this.init_Z_I_BlockPos(owner, target.pos().relative(target.wanted().getValue(BlockStateProperties.FACING_HOPPER)));
   }

   private boolean init_Z_I_BlockPos(int owner, BlockPos at) {
      PrintTarget target = this.targets[owner];
      if (target.wanted().getBlock() instanceof HopperBlock && this.view.getBlockState(at).isAir()) {
         Direction outlet = target.wanted().getValue(BlockStateProperties.FACING_HOPPER);
         if (outlet.getAxis().isHorizontal() && target.pos().relative(outlet).equals(at)) {
            int other = this.cellIndexByPos.get(at.asLong());
            return other >= 0
                  && this.cellStates[other] == 0
                  && this.targets[other].kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.PLACE
                  && this.targets[other].item() instanceof BlockItem
               ? this.targets[other].wanted().getBlock() instanceof HopperBlock
                     && this.targets[other].wanted().getValue(BlockStateProperties.FACING_HOPPER) == outlet.getOpposite()
                  || !this.read_Z_I(other)
               : false;
         } else {
            return false;
         }
      } else {
         return false;
      }
   }

