   private autismclient.ai.print.PrintClicks.Inner_StreamUtil supportClick(
      int owner, PrintTarget support, Vec3 feet, autismclient.ai.print.PrintClicks.Inner_DataUtil budget
   ) {
      PrintTarget target = this.targets[owner];
      this.view.pushTemporaryHypothesis(support.pos(), support.wanted());

      try {
         return PrintClicks.findClick(
            this.view,
            this.env,
            this.rules,
            target,
            target.item(),
            PrintClicks.Inner_CachePool.PLACE,
            feet,
            true,
            false,
            budget,
            4.1000000000000005,
            this.constraintFor(owner),
            support.pos()
         );
      } finally {
         this.view.popHypothesis(support.pos());
      }
   }

   private PrintCore.aM supportWitness(int owner, PrintTarget support) {
      return this.supportWitness(owner, support, false);
   }

   private PrintCore.aM supportWitness(int owner, PrintTarget support, boolean requireRecovery) {
      PrintCore.i goal = this.supportGoal(owner, support, requireRecovery);
      if (goal == null) {
         return null;
      }

      autismclient.ai.print.PrintClicks.Inner_StreamUtil source = this.supportClick(
         owner, support, goal.click.feet(), new autismclient.ai.print.PrintClicks.Inner_DataUtil(2000)
      );
      if (source == null) {
         return null;
      }

      LongOpenHashSet keep = new LongOpenHashSet();
      this.keepPlannedRoute(goal.route, keep);
      keepRouteCells(goal.click.feet(), goal.supportEscape, keep);
      collectTraversedBlocks(goal.click.eye(), goal.click.result().getLocation(), keep);
      collectTraversedBlocks(source.eye(), source.result().getLocation(), keep);
      if (goal.supportRecoveryKeep != null) {
         keep.addAll(goal.supportRecoveryKeep);
      }

      keep.remove(goal.click.support().asLong());
      keep.remove(this.targets[owner].pos().asLong());
      keep.add(support.pos().asLong());
      return this.makeWitness(goal.route.goal(), keep, goal.click.feet(), goal.click.support());
   }

   int inventoryCount(Item item) {
      int n = 0;

      for (int s = 0; s < 36; s++) {
         ItemStack st = this.env.getInventoryItem(s);
         if (st.is(item)) {
            n += st.getCount();
         }
      }

      if (this.env.getInventoryItem(40).is(item)) {
         n += this.env.getInventoryItem(40).getCount();
      }

      return n;
   }

   public static boolean matchesItem(ItemStack stack, Item item) {
      if (stack.is(item)) {
         return true;
      } else if (Compat263.isHoe(item)) {
         return Compat263.isHoe(stack.getItem());
      } else {
         return Compat263.isShovel(item) ? Compat263.isShovel(stack.getItem()) : false;
      }
   }

   boolean prepareHandItem(Item item, PrintControls c) {
      if (!this.env.isHandReady()) {
         this.reason = "Waiting for the hand";
         return false;
      }

      if (matchesItem(this.env.getInventoryItem(this.env.getSelectedHotbarSlot()), item)) {
         if (this.requestedItem == item) {
            this.requestedItem = null;
         }

         this.remainingNeeds.remove(item);
         this.givenUpItems.remove(item);
         this.recoveryAttempted.remove(item);
         return true;
      } else {
         for (int s = 0; s < 9; s++) {
            if (matchesItem(this.env.getInventoryItem(s), item)) {
               c.selectHotbarSlot = s;
               return false;
            }
         }

         for (int s = 9; s < 36; s++) {
            if (matchesItem(this.env.getInventoryItem(s), item)) {
               int to = this.data();
               c.swapSourceSlot = s;
               c.swapHotbarSlot = to;
               c.selectHotbarSlot = to;
               return false;
            }
         }

         if (matchesItem(this.env.getInventoryItem(40), item)) {
            int to = item == Items.AIR ? this.env.getSelectedHotbarSlot() : this.data();
            c.swapSourceSlot = 40;
            c.swapHotbarSlot = to;
            c.selectHotbarSlot = to;
            return false;
         }

         this.requestedItem = item;
         this.missingHandItem = item;
         if (!this.isItemAvailable(item) || this.phase != PrintCore.J.TEARDOWN && this.phase != PrintCore.J.VERIFY) {
            this.reason = "Awaiting material: " + BuiltInRegistries.ITEM.getKey(item);
            this.env.requestCreativeItem(item);
            if (this.env.creativeStockError() != null) {
               this.reason = this.env.creativeStockError();
            } else if (this.env.isCreativeMode()) {
               this.reason = "Obtaining Creative material: " + BuiltInRegistries.ITEM.getKey(item);
            }

            return false;
         } else {
            this.reason = "Recovering temporary material: " + BuiltInRegistries.ITEM.getKey(item);
            return false;
         }
      }
   }

   private int data() {
      for (int s = 0; s < 9; s++) {
         if (this.env.getInventoryItem(s).isEmpty()) {
            return s;
         }
      }

      int sel = this.env.getSelectedHotbarSlot();
      return (sel + 1) % 9;
   }

   float[] stepLookToward(PrintControls c, float yaw, float pitch) {
      float cy = this.env.playerYaw();
      float cp = this.env.playerPitch();
      float dy = PrintGeometry.yawDelta(cy, yaw);
      float ny = cy + Math.max(-60.0F, Math.min(60.0F, dy));
      float np = cp + Math.max(-45.0F, Math.min(45.0F, pitch - cp));
      c.yaw = ny;
      c.pitch = np;
      return new float[]{ny, np};
   }

   boolean isAimAligned(float yaw, float pitch) {
      return this.isAimAligned(yaw, pitch, true);
   }

   boolean isAimAligned(float yaw, float pitch, boolean headYaw) {
      if (!(Math.abs(PrintGeometry.yawDelta(this.env.playerYaw(), yaw)) < 0.6)
         || !(Math.abs(this.env.playerPitch() - pitch) < 0.6)
         || !(Math.abs(PrintGeometry.yawDelta(this.env.serverYaw(), yaw)) < 0.6)
         || !(Math.abs(this.env.serverPitch() - pitch) < 0.6)) {
         return false;
      }

      if (!headYaw) {
         return true;
      }

      Boolean head = this.env.isHeadRotationAligned(yaw, pitch);
      return head != null ? head && this.steadyAimTicks >= 1 : this.steadyAimTicks >= 5 && this.env.nanoTime() - this.aimChangedNanos >= 150000000L;
   }

   private boolean isAimReadyFor(PrintTarget target, float yaw, float pitch) {
      boolean head = hasSixWayLookFacing(target.wanted());
      if (this.isAimAligned(yaw, pitch, head)) {
         return true;
      }

      if (head && this.env.isHeadRotationAligned(yaw, pitch) == null && this.isAimAligned(yaw, pitch, false)) {
         Direction wanted = autismclient.ai.engine.AiPlacementContext.init(yaw, pitch)[0];
         if (!this.headWindow.init(wanted, this.env.nanoTime())) {
            return false;
         }

         this.headFacingProofReuses++;
         return true;
      } else {
         return false;
      }
   }

   static boolean hasSixWayLookFacing(BlockState wanted) {
      Block b = wanted.getBlock();
      return b instanceof PistonBaseBlock
         || b instanceof ObserverBlock
         || b instanceof DispenserBlock
         || b instanceof CrafterBlock
         || b instanceof BarrelBlock
         || b instanceof EndRodBlock
         || b instanceof LightningRodBlock;
   }

