   private PrintCore.PrintStep chainedFluidStep() {
      if (this.fluid == null || this.env.currentTick() - this.lastStrayFluidTick < 35L) {
         return null;
      }

      if (this.strayFluidCheckRevision == this.view.worldMutationRevision()) {
         return null;
      }

      this.strayFluidCheckRevision = this.view.worldMutationRevision();
      autismclient.ai.engine.AiPhysics.MotionState body = this.env.playerMotionState();
      if (!body.onGround()) {
         return null;
      }

      BlockPos here = PrintNav.resolveStandingCell(this.view, new Vec3(body.x(), body.y(), body.z()));
      this.only = this.fluid;

      try {
         return this.pourStep(this.reachFrom(here));
      } finally {
         this.only = null;
      }
   }

