   List<PrintCore.ay> fallingFlowList() {
      if (this.fallingFlows != null) {
         return this.fallingFlows;
      }

      this.fallingFlows = new ArrayList<>();

      for (int i = 0; i < this.targets.length; i++) {
         if (this.targets[i].kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLOW && this.fluidLevel(i) == 1) {
            BlockPos f = this.targets[i].pos();
            int above = this.cellIndexByPos.get(f.above().asLong());
            if (above < 0
               || this.targets[above].kind() != autismclient.ai.print.PrintTarget.Inner_DataUtil.FLUID
                  && this.targets[above].kind() != autismclient.ai.print.PrintTarget.Inner_DataUtil.FLOW) {
               boolean fed = false;
               BlockPos falling = null;

               for (Direction d : Plane.HORIZONTAL) {
                  BlockPos m = f.relative(d);
                  int j = this.cellIndexByPos.get(m.asLong());
                  if (j >= 0) {
                     BlockState w = this.targets[j].wanted();
                     if (this.targets[j].kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLUID
                        || w.hasProperty(BlockStateProperties.WATERLOGGED) && w.getValue(BlockStateProperties.WATERLOGGED)) {
                        fed = true;
                        break;
                     }

                     if (this.targets[j].kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLOW) {
                        int lm = this.fluidLevel(j);
                        boolean floor = this.stop(m.below());
                        if ((lm == 8 || lm == 0) && floor) {
                           fed = true;
                           break;
                        }

                        if (lm == 8 && !floor && falling == null) {
                           falling = m;
                        }
                     }
                  }
               }

               if (!fed && falling != null) {
                  List<BlockPos> shut = new ArrayList<>();

                  for (Direction e : Plane.HORIZONTAL) {
                     BlockPos o = falling.relative(e);
                     int oi = this.cellIndexByPos.get(o.asLong());
                     if (!o.equals(f)
                        && (oi < 0 || this.targets[oi].wanted().isAir())
                        && this.view.getBlockState(o).getCollisionShape(this.view, o).isEmpty()
                        && !this.stop(o.below())) {
                        shut.add(o.below().immutable());
                     }
                  }

                  this.fallingFlows.add(new PrintCore.ay(i, falling.immutable(), falling.below().immutable(), shut));
                  this.logTrace(
                     "shape: "
                        + f.toShortString()
                        + " is made with a block at "
                        + falling.below().toShortString()
                        + " under "
                        + falling.toShortString()
                        + (shut.isEmpty() ? "" : ", ways down shut at " + shut)
                  );
               }
            }
         }
      }

      return this.fallingFlows;
   }

   boolean sync_Z_J(long key) {
      this.spillShapeList();
      List<PrintCore.aB> sourceOwners = this.spillShapesByFloor.get(key);
      if (sourceOwners != null) {
         for (PrintCore.aB shape : sourceOwners) {
            if (!this.read_Z_UiHelper_aB(shape)) {
               return true;
            }
         }
      }

      if (this.fallingFlows == null) {
         return false;
      }

      for (PrintCore.ay s : this.fallingFlows) {
         boolean under = s.under.asLong() == key;
         boolean shut = false;

         for (BlockPos x : s.shut) {
            if (x.asLong() == key) {
               shut = true;
               break;
            }
         }

         if (under || shut) {
            if (this.activePolicy != null) {
               Integer previous = this.activePolicy.fallingFlowStates.put(s, s.load_I);
               Boolean dry = this.activePolicy.fallingFlowDry.put(s, s.init_J == -9223372036854775808L);
               if (previous != null && (previous != s.load_I || dry != (s.init_J == -9223372036854775808L))) {
                  this.activePolicy.verdictChanged = true;
               }
            }

            if (s.load_I != -1) {
               if (under && s.load_I != 2 && s.init_J == -9223372036854775808L && s.load_I == 1) {
                  return true;
               }

               if (shut && this.temporaryBlocks.containsKey(s.under.asLong())) {
                  return true;
               }
            }
         }
      }

      return false;
   }

   private boolean tick_Z_J(long key) {
      if (this.isSpillFloor(key)) {
         return true;
      }

      if (this.fallingFlows == null) {
         return false;
      }

      for (PrintCore.ay shape : this.fallingFlows) {
         if (shape.load_I == 0 || shape.load_I == 1) {
            if (shape.under.asLong() == key) {
               return true;
            }

            for (BlockPos block : shape.shut) {
               if (block.asLong() == key) {
                  return true;
               }
            }
         }
      }

      return false;
   }

   private PrintCore.PrintStep fallingFlowStep(PrintNav.Inner_TaskQueue reach) {
      for (PrintCore.ay s : this.fallingFlowList()) {
         if (s.load_I == 0 && this.predictedFlow.contains(s.falling.asLong())) {
            if (!this.view.getBlockState(s.falling).getFluidState().isEmpty()) {
               s.load_I = -1;
               this.logTrace(
                  "shape: water reached "
                     + s.falling.toShortString()
                     + " first; "
                     + this.targets[s.cell].pos().toShortString()
                     + " comes as it will"
               );
            } else {
               BlockPos missing = null;

               for (BlockPos p : s.init()) {
                  if (this.view.getBlockState(p).getCollisionShape(this.view, p).isEmpty()) {
                     missing = p;
                     break;
                  }
               }

               if (missing != null) {
                  if (this.pendingTemporary.containsKey(missing.asLong())) {
                     return this.waitOneTick;
                  }

                  if (!this.abandonedCells.contains(missing.asLong())) {
                     PrintCore.PrintStep place = this.placeTemporaryStep(
                        reach, missing, "shape: a block at " + missing.toShortString() + " for " + this.targets[s.cell].pos().toShortString()
                     );
                     if (place != null) {
                        return place;
                     }

                     if (this.count_LongOpenHashSet.add(cellStanceKey(s.cell, reach.startKey))) {
                        Item temp = this.tempItem();
                        BlockState tempState = temp instanceof BlockItem bi ? bi.getBlock().defaultBlockState() : null;
                        LongArrayList cells = new LongArrayList();
                        cells.add(missing.asLong());
                        PrintAccess access = new PrintAccess(this, 80.0);
                        PrintAccess.Inner_BufferHelper plan = tempState == null
                           ? null
                           : access.planToCells(BlockPos.of(reach.startKey), reach.feetYOf(reach.startKey), cells, tempState, temp, 20000);
                        if (plan != null && !plan.steps().isEmpty()) {
                           this.logTrace(
                              "shape: access plan "
                                 + plan.steps().size()
                                 + " steps toward "
                                 + missing.toShortString()
                                 + " ("
                                 + describePlan(plan)
                                 + ")"
                           );
                           return new PrintCore.AccessPlanStep(plan, temp);
                        }

                        this.logTrace("shape: no access to " + missing.toShortString() + (plan == null ? ": " + access.failureDetail : ""));
                     }
                  }

                  s.load_I = -1;
                  this.logTrace(
                     "shape: no stance places " + missing.toShortString() + "; " + this.targets[s.cell].pos().toShortString() + " comes as it will"
                  );
               } else {
                  for (BlockPos in : List.of(this.targets[s.cell].pos(), s.falling)) {
                     if (this.temporaryBlocks.containsKey(in.asLong())) {
                        if (this.pendingTemporary.containsKey(in.asLong())) {
                           return this.waitOneTick;
                        }

                        PrintCore.PrintStep dig = this.digStep(
                           reach, in, "shape: " + this.targets[s.cell].pos().toShortString() + " must stay open"
                        );
                        if (dig != null) {
                           return dig;
                        }

                        PrintCore.PrintStep climb = this.approachStep(BlockPos.of(reach.startKey), in, "shape");
                        if (climb != null) {
                           return climb;
                        }

                        return this.waitOneTick;
                     }
                  }

                  s.load_I = 1;
                  this.logTrace("shape: the blocks for " + this.targets[s.cell].pos().toShortString() + " stand; its water may come");
               }
            }
         }
      }

      return null;
   }

   private PrintCore.PrintStep init_UiHelper_NetHelper_BlockPos_Z(BlockPos here, boolean waitHere) {
      PrintNav.Inner_TaskQueue reach = null;

      for (PrintCore.ay s : this.fallingFlowList()) {
         if (s.load_I == 1) {
            if (this.view.getBlockState(s.falling).getFluidState().isEmpty()) {
               if (waitHere && !this.valid_Z()) {
                  s.load_I = 2;
                  this.logTrace("shape: no water came to " + s.falling.toShortString());
               }
            } else {
               if (s.init_J == -9223372036854775808L) {
                  s.init_J = this.env.currentTick();
               }

               boolean filled = !this.view.getBlockState(this.targets[s.cell].pos()).getFluidState().isEmpty();
               if (!filled && this.env.currentTick() - s.init_J < 100L) {
                  if (waitHere) {
                     this.reason = "Shaping the flow at " + this.targets[s.cell].pos().toShortString();
                     return new PrintCore.aK(1);
                  }
               } else {
                  if (!filled) {
                     this.logTrace("shape: " + this.targets[s.cell].pos().toShortString() + " never filled (" + this.describeFallingFlow(s) + ")");
                  } else if (this.env.currentTick() - s.init_J < 20L) {
                     if (waitHere) {
                        return new PrintCore.aK(1);
                     }
                     continue;
                  }

                  boolean left = false;
                  Iterator var8 = s.init().iterator();

                  while (true) {
                     if (var8.hasNext()) {
                        BlockPos p = (BlockPos)var8.next();
                        if (!this.temporaryBlocks.containsKey(p.asLong())) {
                           continue;
                        }

                        left = true;
                        if (reach == null) {
                           reach = this.reachFrom(here);
                        }

                        PrintCore.PrintStep dig = this.digStep(
                           reach, p, "shape: " + this.targets[s.cell].pos().toShortString() + " holds its water"
                        );
                        if (dig != null) {
                           return dig;
                        }

                        PrintCore.PrintStep climb = this.approachStep(here, p, "shape");
                        if (climb != null) {
                           return climb;
                        }
                     }

                     if (!left) {
                        s.load_I = 2;
                        this.logTrace("shape: " + this.targets[s.cell].pos().toShortString() + " is shaped");
                     }
                     break;
                  }
               }
            }
         }
      }

      return null;
   }

   private String describeFallingFlow(PrintCore.ay s) {
      StringBuilder b = new StringBuilder(this.describeBlock(s.falling) + " over " + this.describeBlock(s.under));

      for (Direction d : Plane.HORIZONTAL) {
         BlockPos o = s.falling.relative(d);
         b.append("; ").append(d.getName()).append(' ').append(this.describeBlock(o)).append(" over ").append(this.describeBlock(o.below()));
      }

      return b.toString();
   }

   private String describeBlock(BlockPos p) {
      BlockState st = this.view.getBlockState(p);
      String name = BuiltInRegistries.BLOCK.getKey(st.getBlock()).getPath();
      if (!st.getFluidState().isEmpty()) {
         name = name + "/" + st.getFluidState().getAmount() + (st.getFluidState().isSource() ? "s" : "");
      }

      return name;
   }

