   final class TempScaffoldStep implements PrintCore.PrintStep {
      final int cell;
      final BlockPos init_BlockPos;
      final long stanceKey;
      final boolean crouch;
      final Vec3 workFeet;
      int load_I;
      boolean load_Z;
      PrintCore.PrintStep init_UiHelper_NetHelper;
      PrintCore.ClickCandidatePlanner init_UiHelper_PathHelpe;

      TempScaffoldStep(int cell, BlockPos temp, long stanceKey, boolean crouch, Vec3 workFeet) {
         this.cell = cell;
         this.init_BlockPos = temp;
         this.stanceKey = stanceKey;
         this.crouch = crouch;
         this.workFeet = workFeet;
      }

      @Override
      public PrintControls tick() {
         PrintCore.this.reason = "Lighting the copper bulb";
         this.load_I++;
         boolean there = PrintCore.this.view.getBlockState(this.init_BlockPos).is(Blocks.REDSTONE_BLOCK);
         boolean lit = !AiPrintRules.needsBulbPulse(
            PrintCore.this.targets[this.cell].wanted(), PrintCore.this.view.getBlockState(PrintCore.this.targets[this.cell].pos())
         );
         if (!there) {
            if (this.load_I > 12) {
               PrintCore.this.logTrace("bulb: the pulse block never stood at " + this.init_BlockPos.toShortString());
               this.load_Z = true;
            }

            return PrintCore.this.idleControls();
         } else {
            if (!lit && this.load_I < 40) {
               return PrintCore.this.idleControls();
            }

            if (PrintCore.this.env.canUseFlight()) {
               if (this.init_UiHelper_PathHelpe == null) {
                  this.init_UiHelper_PathHelpe = PrintCore.this.new ClickCandidatePlanner(
                     new PrintTarget(
                        -1,
                        this.init_BlockPos,
                        PrintCore.this.view.getBlockState(this.init_BlockPos),
                        autismclient.ai.print.PrintTarget.Inner_DataUtil.PLACE,
                        Items.AIR,
                        null
                     ),
                     PrintClicks.Inner_CachePool.DIG,
                     Items.AIR,
                     null,
                     true
                  );
               }

               if (!this.init_UiHelper_PathHelpe.close && !PrintCore.this.isBudgetSpent()) {
                  this.init_UiHelper_PathHelpe.init(PrintCore.this.workBudget());
               }

               if (!this.init_UiHelper_PathHelpe.close) {
                  return PrintCore.this.idleControls();
               }

               if (this.init_UiHelper_PathHelpe.init_UiHelper_i != null) {
                  this.init_UiHelper_NetHelper = this.init_UiHelper_PathHelpe.init_UiHelper_i.ground == null
                     ? PrintCore.this.new ValueSink(-1, this.init_BlockPos, this.init_UiHelper_PathHelpe.init_UiHelper_i)
                     : PrintCore.this.new FlightLandingStep(-1, this.init_UiHelper_PathHelpe.init_UiHelper_i);
               } else {
                  PrintCore.this.cleanupCandidates.add(this.init_BlockPos.asLong());
               }

               this.load_Z = true;
               return PrintCore.this.idleControls();
            } else {
               PrintCore.this.logTrace(
                  "bulb: "
                     + PrintCore.this.targets[this.cell].pos().toShortString()
                     + (lit ? " lit" : " still unlit")
                     + "; taking the pulse block away"
               );
               this.init_UiHelper_NetHelper = PrintCore.this.new StreamGate(this.init_BlockPos, false, this.stanceKey, this.crouch, this.workFeet);
               this.load_Z = true;
               return PrintCore.this.idleControls();
            }
         }
      }

      @Override
      public boolean isDone() {
         return this.load_Z;
      }

      @Override
      public PrintCore.PrintStep next() {
         return this.init_UiHelper_NetHelper;
      }
   }

   final class ClusterWorkContext {
      final List<Integer> ready;
      final Vec3 origin;
      final PrintSpatialIndex.Inner_ConfigStore cellSearch;
      final ArrayList<Vec3> poses = new ArrayList<>();
      int poseCursor;
      boolean init_Z;
      boolean load_Z;
      double init_D;
      boolean read;
      boolean write;
      int previewAttempts;
      PrintCore.PrintStep work;
      final ArrayList<PrintCore.g> previews = new ArrayList<>();

      ClusterWorkContext(List<Integer> ready, Vec3 origin) {
         this.ready = ready;
         this.origin = origin;
         PrintCore.this.ensureSpatialIndex();
         this.cellSearch = PrintCore.this.spatialIndex
            .startSearch(origin, 2147483647, 64, i -> PrintCore.this.cellStates[i] == 0 && PrintCore.this.value(i) && !PrintCore.this.set(i));
      }

      void init(long allowance) {
         long began = PrintCore.this.view.workUnits();
         long startedNanos = System.nanoTime();
         if (!this.cellSearch.done) {
            this.cellSearch.init(1024, PrintCore.this.view::workUnits, allowance);
            if (!this.cellSearch.done) {
               return;
            }
         }

         if (!this.init_Z) {
            this.init_Z = true;
            if (this.cellSearch.exhausted || this.cellSearch.results.size() < 8) {
               this.load_Z = true;
               return;
            }

            int x0 = 2147483647;
            int y0 = x0;
            int z0 = x0;
            int x1 = -2147483648;
            int y1 = x1;
            int z1 = x1;

            for (int i : this.cellSearch.results) {
               BlockPos p = PrintCore.this.targets[i].pos();
               x0 = Math.min(x0, p.getX());
               y0 = Math.min(y0, p.getY());
               z0 = Math.min(z0, p.getZ());
               x1 = Math.max(x1, p.getX());
               y1 = Math.max(y1, p.getY());
               z1 = Math.max(z1, p.getZ());
            }

            this.read = y0 == y1;
            this.write = x1 - x0 < 5 && z1 - z0 < 5 && y1 - y0 < 4;

            for (int i : this.cellSearch.results) {
               if (PrintCore.hasSixWayLookFacing(PrintCore.this.targets[i].wanted())) {
                  this.write = false;
               }
            }

            double x = (x0 + x1 + 1) * 0.5;
            double z = (z0 + z1 + 1) * 0.5;
            double middle = this.read ? y0 - 1.8 - 0.25 : (y0 + y1 + 1) * 0.5 - 1.62 + 0.08;
            this.poses.add(new Vec3(x, y1 + 1.15, z));
            this.poses.add(new Vec3(x, y0 - 1.8 - 0.15, z));

            for (double y : new double[]{this.read ? middle : Math.max(y0 + 0.15, middle), y0 + 0.15}) {
               this.poses.add(new Vec3(x, y, z0 - 2.5));
               this.poses.add(new Vec3(x, y, z1 + 3.5));
               this.poses.add(new Vec3(x0 - 2.5, y, z));
               this.poses.add(new Vec3(x1 + 3.5, y, z));
            }

            int anchors = 0;

            for (int i : this.ready) {
               if (anchors >= 4) {
                  break;
               }

               if (PrintCore.this.value(i)
                  && PrintClicks.hasPlaceableSupport(PrintCore.this.view, PrintCore.this.targets[i], PrintCore.this.constraintFor(i), null)) {
                  BlockPos at = PrintCore.this.targets[i].pos();
                  double eye = this.read ? middle + 1.62 : at.getY() + 0.5;

                  for (Direction side : Plane.HORIZONTAL) {
                     this.poses.add(new Vec3(at.getX() + 0.5 + side.getStepX() * 3, eye - 1.62, at.getZ() + 0.5 + side.getStepZ() * 3));
                     boolean head = PrintCore.hasSixWayLookFacing(PrintCore.this.targets[i].wanted());
                     double bandEye = at.getY() + (head ? 2.08 : 3.08);
                     double distance = head ? 2.75 : 2.0;
                     this.poses
                        .add(new Vec3(at.getX() + 0.5 + side.getStepX() * distance, bandEye - 1.62, at.getZ() + 0.5 + side.getStepZ() * distance));
                  }

                  anchors++;
               }
            }

            this.poses.sort(Comparator.<Vec3>comparingDouble(posex -> this.init(posex) - this.origin.distanceTo(posex) * 0.65).reversed());
            this.init_D = 0.0;
         }

         label136:
         while (this.poseCursor < this.poses.size() && PrintCore.this.view.workUnits() - began < allowance) {
            Vec3 pose = this.poses.get(this.poseCursor++);
            double distance = this.origin.distanceTo(pose);
            if (!(distance < 0.5)
               && !(distance > 16.0)
               && this.init(pose) >= 3
               && PrintFlight.isFlightPointSafe(PrintCore.this.view, pose)
               && PrintFlight.isFlightSegmentClear(PrintCore.this.view, this.origin, pose)) {
               autismclient.ai.print.PrintClicks.Inner_DataUtil budget = new autismclient.ai.print.PrintClicks.Inner_DataUtil(1200);

               for (int checked = 0; checked < Math.min(64, this.ready.size()) && !budget.isExhausted(); checked++) {
                  int i = this.ready.get(checked);
                  if (PrintCore.this.buffer(i)
                     && PrintCore.this.value(i)
                     && PrintCore.this.stop(i)
                     && !PrintCore.this.refusedCellStances.contains(PrintCore.cellStanceKey(i, BlockPos.containing(pose).asLong()))) {
                     PrintTarget target = PrintCore.this.targets[i];
                     autismclient.ai.print.PrintClicks.Inner_StreamUtil click = PrintClicks.findClick(
                        PrintCore.this.view,
                        PrintCore.this.env,
                        PrintCore.this.rules,
                        target,
                        target.item(),
                        PrintClicks.Inner_CachePool.PLACE,
                        pose,
                        true,
                        false,
                        budget,
                        4.4,
                        PrintCore.this.constraintFor(i),
                        null
                     );
                     if (click != null) {
                        if (this.previewAttempts++ >= 8) {
                           this.poseCursor = this.poses.size();
                        } else {
                           PrintCore.l preview = PrintCore.this.previewActions(pose, click, this.cellSearch.results, budget);
                           if (preview.cells().size() >= 2) {
                              this.previews.add(new PrintCore.g(pose, click, preview));
                           }
                        }

                        if (System.nanoTime() - startedNanos >= 2000000L) {
                           break label136;
                        }
                        continue label136;
                     }
                  }
               }
               break;
            }
         }

         this.load_Z = this.poseCursor >= this.poses.size();
         if (this.load_Z) {
            this.init_V();
         }
      }

      private void init_V() {
         Vec3 at = PrintCore.this.feetPosition();
         autismclient.ai.engine.AiPhysics.MotionState coast = PrintCore.this.env.playerMotionState();

         for (int tick = 0; tick < 26; tick++) {
            coast = PrintFlight.simulateFlightTick(
               coast,
               autismclient.ai.print.PrintMover.Inner_StreamUtil.NONE,
               PrintCore.this.env.playerYaw(),
               PrintCore.this.env.flyingSpeed(),
               PrintCore.this.env.livePhysicsWorld()
            );
         }

         double best = 0.0;

         for (PrintCore.g choice : this.previews) {
            Vec3 pose = choice.pose();
            if (PrintFlight.isFlightSegmentClear(PrintCore.this.view, at, pose) && PrintFlight.isFlightSegmentClear(PrintCore.this.view, coast.position(), pose)) {
               double horizontal = Math.hypot(pose.x - at.x, pose.z - at.z);
               double travel = 4.0 + Math.max(horizontal / 0.5, Math.abs(pose.y - at.y) / 0.225);
               double score = choice.preview().cells().size() / (choice.preview().ticks() + travel);
               if (!(score <= best)) {
                  best = score;
                  PrintFlight.Inner_BufferHelper route = new PrintFlight.Inner_BufferHelper(List.of(pose), BlockPos.containing(pose).asLong());
                  PrintCore.ValueSink work = PrintCore.this.new ValueSink(choice.first().target().index(), null, new PrintCore.i(route, choice.first()));
                  work.init_List = choice.preview().cells();
                  work.init_Vec3 = this.write ? null : pose;
                  if (this.read && pose.y + 1.8 < this.firstResultY() - 0.05) {
                     work.ceiling = this.firstResultY() - 1.8 - 0.08;
                  }

                  this.work = work;
               }
            }
         }
      }

      private int firstResultY() {
         return PrintCore.this.targets[this.cellSearch.results.getInt(0)].pos().getY();
      }

      private int init(Vec3 pose) {
         int count = 0;
         Vec3 eye = pose.add(0.0, 1.62, 0.0);
         AABB body = PrintGeometry.init(pose.x, pose.y, pose.z, false);

         for (int i : this.cellSearch.results) {
            PrintTarget target = PrintCore.this.targets[i];
            BlockPos at = target.pos();
            if (at.getX() + 1 > body.minX
               && at.getX() < body.maxX
               && at.getY() + 1 > body.minY
               && at.getY() < body.maxY
               && at.getZ() + 1 > body.minZ
               && at.getZ() < body.maxZ) {
               return 0;
            }

            if (target.pos().distToCenterSqr(eye) < 19.360000000000003) {
               count++;
            }
         }

         return count;
      }
   }

   private final class CellEditSnapshot {
      final long key;
      int changeKind;
      BlockState liveState;
      int[] affectedWitnesses;
      int load;

      CellEditSnapshot(long key, BlockState before) {
         this.key = key;
         if (PrintCore.this.env.hasChunkAt(BlockPos.of(key))) {
            if (PrintCore.this.machineOutcomes.containsKey(key)) {
               PrintCore.this.outcomeChecks.add(key);
            }

            if (!PrintCore.this.isWatchedPosition(key)) {
               PrintCore.this.view.appendChangeRing(key);
               PrintCore.this.cleanupAccess.read(key);
               PrintCore.this.view.invalidateAround(key);
            } else {
               BlockState arrived = PrintCore.this.env.getBlockState(BlockPos.of(key));
               if (PrintCore.this.spillShapeByCell != null) {
                  for (Direction direction : Direction.values()) {
                     int source = PrintCore.this.cellIndexByPos.get(BlockPos.offset(key, direction));
                     PrintCore.aB shape = PrintCore.this.spillShapeByCell.get(source);
                     if (shape != null) {
                        shape.lastChangeTick = PrintCore.this.env.currentTick();
                     }
                  }
               }

               this.changeKind = PrintCore.this.classifyChange(key, before, arrived);
               PrintCore.this.changeCounts[this.changeKind]++;
               if (this.changeKind == 2 && PrintCore.this.changeLog.size() < 40) {
                  PrintCore.this.changeLog.add(BlockPos.of(key).toShortString() + " " + before + " -> " + arrived);
               }

               if (this.changeKind != 0) {
                  PrintCore.this.key = key;
                  PrintCore.this.before = before;
                  PrintCore.this.arrived = arrived;
                  PrintCore.this.observedChangeKind = this.changeKind;
               }

               if (this.changeKind == 0) {
                  PrintCore.this.view.onLiveStateChanged(key);
               } else if (this.changeKind == 1) {
                  PrintCore.this.view.onWorldBlockAdded(key);
               } else {
                  PrintCore.this.view.onWorldBlockRemoved(key);
               }

               if (this.changeKind != 0) {
                  PrintCore.this.cleanupAccess.read(key);
               }

               this.liveState = PrintCore.this.env.getBlockState(BlockPos.of(key));
               if (PrintCore.this.excavatedCells.contains(key) && this.liveState.isAir()) {
                  PrintCore.this.confirmedAirCells.add(key);
               }

               this.affectedWitnesses = PrintCore.this.witnessCache.witnessesAt(key);
            }
         }
      }

      boolean advanceEdit() {
         if (this.affectedWitnesses == null) {
            return true;
         }

         if (this.load < this.affectedWitnesses.length) {
            int witnessId = this.affectedWitnesses[this.load++];
            PrintCore.aM witness = PrintCore.this.witnessCache.load(witnessId);
            if (witness == null) {
               return false;
            }

            BlockState expected = witness.required().get(this.key);
            if (witness.touches(this.key) || expected != null && expected != this.liveState) {
               if (this.changeKind == 0 && witness.required() instanceof Long2ObjectOpenHashMap<BlockState> required) {
                  if (expected != null) {
                     required.put(this.key, this.liveState);
                  }

                  return false;
               } else {
                  if (witness.flightAccess() != null) {
                     return false;
                  }

                  PrintCore.this.evictions[witness.touches(this.key) ? this.changeKind : 3 + this.changeKind]++;
                  PrintCore.this.editStepsThisTick = PrintCore.this.editStepsThisTick + PrintCore.this.witnessCache.cellCount(witnessId);
                  PrintCore.this.witnessCache.read(witnessId);
                  return false;
               }
            } else {
               return false;
            }
         } else {
            this.applyEdit();
            return true;
         }
      }

      private void applyEdit() {
         if (PrintCore.this.env.hasChunkAt(BlockPos.of(this.key))) {
            int self = PrintCore.this.cellIndexByPos.get(this.key);
            if (self >= 0) {
               PrintCore.this.editStepsThisTick = PrintCore.this.editStepsThisTick + PrintCore.this.witnessCache.cellCount(self);
               PrintCore.this.witnessCache.read(self);
               PrintCore.this.witnessMisses.load(self);
               PrintCore.this.clickReachCache.remove(self);
            }

            byte statusBefore = self >= 0 ? PrintCore.this.cellStates[self] : 0;
            if (!this.liveState.getFluidState().isEmpty()) {
               PrintCore.this.lastFluidChangeTick = PrintCore.this.env.currentTick();
               if (this.liveState.getFluidState().getType().isSame(Fluids.LAVA)) {
                  PrintCore.this.lastLavaChangeTick = PrintCore.this.env.currentTick();
               }

               int fi = PrintCore.this.cellIndexByPos.get(this.key);
               Fluid fluid = this.liveState.getFluidState().getType();
               boolean contained = fi >= 0
                  && (
                     PrintCore.this.targets[fi].kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLUID
                        || PrintCore.this.targets[fi].kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.FLOW
                  )
                  && PrintCore.this.targets[fi].wanted().getFluidState().getType().isSame(fluid);
               if (contained) {
                  PrintCore.this.fluid = fluid;
               } else {
                  PrintCore.this.lastStrayFluidTick = PrintCore.this.env.currentTick();
               }
            }

            int i = PrintCore.this.cellIndexByPos.get(this.key);
            if (i >= 0) {
               PrintCore.this.refreshCell(i);
               if (this.changeKind == 0 && PrintCore.this.cellStates[i] != statusBefore) {
                  PrintCore.this.view.onWorldBlockRemoved(this.key);
               }

               Block block = PrintCore.this.targets[i].wanted().getBlock();
               if (PrintCore.this.cellProgressTick != null
                  && (
                     PrintCore.write_Z_BlockState(PrintCore.this.targets[i].wanted())
                        || block instanceof ObserverBlock
                        || block instanceof BaseRailBlock
                  )) {
                  PrintCore.this.cellProgressTick[i] = PrintCore.this.env.currentTick();
               }
            }

            if (PrintCore.this.temporaryBlocks.containsKey(this.key)) {
               BlockState now = PrintCore.this.env.getBlockState(BlockPos.of(this.key));
               boolean same = !now.isAir()
                  && now.getFluidState().isEmpty()
                  && !now.canBeReplaced()
                  && (
                     now.getBlock() == PrintCore.this.temporaryBlocks.get(this.key).getBlock()
                        || PrintCore.isDirtLike(now) && PrintCore.isDirtLike(PrintCore.this.temporaryBlocks.get(this.key))
                  );
               if (same && !now.equals(PrintCore.this.temporaryBlocks.get(this.key))) {
                  PrintCore.this.adjustTemporaryItemCount(PrintCore.this.temporaryBlocks.get(this.key).getBlock().asItem(), -1);
                  PrintCore.this.temporaryBlocks.put(this.key, now);
                  PrintCore.this.adjustTemporaryItemCount(now.getBlock().asItem(), 1);
               }

               if (!same) {
                  PrintCore.this.forgetTemporaryBlock(this.key);
               }
            }
         }
      }
   }

