   private final class an implements PrintCore.PrintStep {
      PrintCore.ap dependencyBuild = PrintCore.this.predecessors == null ? PrintCore.this.new ap() : null;
      final IntArrayList inputQueue = new IntArrayList();
      final IntOpenHashSet queuedInputs = new IntOpenHashSet();
      int nextCell;
      int load = -1;
      int read;
      int write;
      int update;
      boolean unlitTorchInput;

      void step() {
         if (this.dependencyBuild != null) {
            if (this.dependencyBuild.invalidated) {
               this.dependencyBuild = PrintCore.this.new ap();
            }

            if (this.dependencyBuild.init()) {
               this.dependencyBuild = null;
            }
         } else if (this.load >= 0) {
            if (this.write == 0) {
               if (this.read < PrintCore.this.predecessors[this.load].length) {
                  BlockState input = PrintCore.this.targets[PrintCore.this.predecessors[this.load][this.read++]].wanted();
                  if ((input.is(Blocks.REDSTONE_TORCH) || input.is(Blocks.REDSTONE_WALL_TORCH)) && !input.getValue(RedstoneTorchBlock.LIT)) {
                     this.unlitTorchInput = true;
                  }
               } else {
                  this.write = 1;
                  this.read = 0;
               }
            } else if (this.read < PrintCore.this.inputCells[this.load].length) {
               int input = PrintCore.this.inputCells[this.load][this.read++];
               long key = PrintCore.this.targets[input].pos().asLong();
               if (PrintCore.this.containerOrder.init_Z(PrintCore.this.targets[input].pos())) {
                  PrintCore.this.pistonsByInput.computeIfAbsent(key, ignored -> new IntArrayList()).add(this.load);
               }

               if (this.unlitTorchInput && this.queuedInputs.add(input)) {
                  this.inputQueue.add(input);
               }
            } else {
               this.load = -1;
            }
         } else if (this.nextCell < PrintCore.this.targets.length) {
            int next = this.nextCell++;
            BlockState state = PrintCore.this.targets[next].wanted();
            if (state.getBlock() instanceof PistonBaseBlock && !state.getValue(PistonBaseBlock.EXTENDED)) {
               this.load = next;
               this.read = this.write = 0;
               this.unlitTorchInput = false;
            }
         } else if (this.update < this.inputQueue.size()) {
            BlockPos at = PrintCore.this.targets[this.inputQueue.getInt(this.update++)].pos();
            if (PrintCore.this.containerOrder.init_Z(at)
               && PrintCore.this.quietInputs.add(at.asLong())
               && PrintCore.this.machineJobs.containsKey(at.asLong())) {
               PrintCore.this.pendingQuietInputs.add(at.asLong());
               PrintCore.this.pendingQuietInputsByY.merge(at.getY(), 1, Integer::sum);
            }

            for (BlockPos dependency : PrintCore.this.containerOrder.dependenciesOf(at)) {
               int input = PrintCore.this.cellIndexByPos.get(dependency.asLong());
               if (input >= 0 && this.queuedInputs.add(input)) {
                  this.inputQueue.add(input);
               }
            }
         } else {
            PrintCore.this.quietInputsOrdered = true;
         }
      }

      @Override
      public PrintControls tick() {
         PrintCore.this.reason = "Ordering quiet machine inventory inputs";
         long deadline = System.nanoTime() + 3000000L;
         long began = PrintCore.this.view.workUnits();
         long allowance = PrintCore.this.workBudget();

         for (int i = 0;
            i < 32768 && !PrintCore.this.quietInputsOrdered && PrintCore.this.view.workUnits() - began < allowance && ((i & 63) != 0 || System.nanoTime() < deadline);
            i++
         ) {
            this.step();
         }

         return PrintCore.this.holdControls();
      }

      @Override
      public boolean isDone() {
         return PrintCore.this.quietInputsOrdered;
      }
   }

   public static final class ao {
      private final List<PrintTarget> targets;
      private PrintSpatialIndex spatialIndex;

      private ao(List<PrintTarget> targets, PrintSpatialIndex index) {
         this.targets = targets;
         this.spatialIndex = index;
      }

      private synchronized PrintSpatialIndex init(List<PrintTarget> targets) {
         if (this.targets != targets) {
            throw new IllegalArgumentException("Prepared geometry belongs to different targets");
         }

         if (this.spatialIndex == null) {
            throw new IllegalStateException("Prepared geometry already bound");
         }

         PrintSpatialIndex result = this.spatialIndex;
         this.spatialIndex = null;
         return result;
      }
   }

