         this.init_BlockPos = near == null ? null : near.immutable();
         BlockPos center = PrintCore.this.targets[target].pos();
         if (PrintCore.this.temporaryBlocks.size() <= 2197) {
            for (long key : PrintCore.this.temporaryBlocks.keySet()) {
               BlockPos at = BlockPos.of(key);
               if (key != blocked && !PrintCore.this.view.hasHypothesisAt(at) && at.distChessboard(center) <= 6) {
                  this.init_LongArrayList.add(key);
               }
            }
         } else {
            for (int dx = -6; dx <= 6; dx++) {
               for (int dy = -6; dy <= 6; dy++) {
                  for (int dz = -6; dz <= 6; dz++) {
                     BlockPos at = center.offset(dx, dy, dz);
                     if (at.asLong() != blocked
                        && PrintCore.this.temporaryBlocks.containsKey(at.asLong())
                        && !PrintCore.this.view.hasHypothesisAt(at)) {
                        this.init_LongArrayList.add(at.asLong());
                     }
                  }
               }
            }
         }
